/** All translations for zizhitongjian ch.014 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起閼逢困敦，盡重光協洽，凡八年。", literal: "From Quefeng Kundun through Chongguang Xieqia; eight years in all.", idiomatic: "From Quefeng Kundun through Chongguang Xieqia—eight years in all." },
  { zh: "1冬，十月，丁酉晦，日有食之。", literal: "1. In winter, the tenth month, on the last day dingyou, there was an eclipse of the sun.", idiomatic: "1. In winter, the tenth month, on the last day dingyou, there was a solar eclipse." },
  { zh: "----2十一月，丁卯晦，日有食之。", literal: "----2 In the eleventh month, on the last day dingmao, there was an eclipse of the sun.", idiomatic: "----2 In the eleventh month, on the last day dingmao, there was a solar eclipse." },
  { zh: "----3詔曰：「前遣列侯之國，或辭未行。", literal: "----3 An edict said: \"Previously I sent the ranked marquises to their states; some declined and have not yet gone.", idiomatic: "----3 An edict said, \"I previously sent the ranked marquises to their states; some declined and have not yet departed." },
  { zh: "丞相，朕之所重，其為朕率列侯之國！", literal: "The chancellor is one whom I hold in weight—let him lead the ranked marquises to their states for me!", idiomatic: "The chancellor is one I hold in the highest regard—let him lead the ranked marquises to their states for me!" },
  { zh: "」十二月，免丞相勃，遣就國。", literal: "\" In the twelfth month, the chancellor Bo was dismissed and sent to his state.", idiomatic: "\" In the twelfth month, Chancellor Bo was dismissed and sent to his state." },
  { zh: "乙亥，以太尉灌嬰為丞相；", literal: "On yihai, the Grand Commandant Guan Ying was made chancellor;", idiomatic: "On yihai, Grand Commandant Guan Ying was made chancellor;" },
  { zh: "罷太尉官，屬丞相。", literal: "the office of Grand Commandant was abolished and subordinated to the chancellor.", idiomatic: "the office of Grand Commandant was abolished and placed under the chancellor." },
  { zh: "----4夏，四月，城陽景王章薨。", literal: "----4 In summer, the fourth month, King Jing of Chengyang, Zhang, died.", idiomatic: "----4 In summer, the fourth month, King Jing of Chengyang, Zhang, died." },
  { zh: "----5初，趙王敖獻美人於高祖，得幸，有娠。", literal: "----5 At the outset, King Ao of Zhao presented a beauty to the High Ancestor; she won favor and became pregnant.", idiomatic: "----5 At the outset, King Ao of Zhao presented a beauty to the High Ancestor; she won his favor and became pregnant." },
  { zh: "及貫高事發，美人亦坐系河內。", literal: "When the affair of Guan Gao broke out, the beauty was also implicated and imprisoned in Henei.", idiomatic: "When the affair of Guan Gao broke out, the beauty was implicated as well and imprisoned in Henei." },
  { zh: "美人母弟趙兼因辟陽侯審食其言-{呂后}-，呂后妒，弗肯白。", literal: "The beauty's younger brother by the same mother, Zhao Jian, spoke through the Marquis of Piyang Shen Yishi to -{呂后}-; the Empress Lü was jealous and would not speak on her behalf.", idiomatic: "The beauty's younger brother Zhao Jian spoke through the Marquis of Piyang Shen Yishi to -{呂后}-; the Empress Lü was jealous and would not plead for her." },
  { zh: "美人已生子，恚，即自殺。", literal: "The beauty had already borne a son; in resentment she at once killed herself.", idiomatic: "The beauty had already borne a son; in rage she killed herself." },
  { zh: "吏奉其子詣上，上悔，名之曰長，令-{呂后}-母之，而葬其母真定。", literal: "An officer presented the son to the emperor; the emperor regretted it, named him Chang, ordered -{呂后}- to mother him, and buried his mother at Zhending.", idiomatic: "An officer brought the son to the emperor; the emperor was filled with regret, named him Chang, had -{呂后}- raise him as mother, and buried his mother at Zhending." },
  { zh: "後封長為淮南王。", literal: "Later Chang was enfeoffed as king of Huainan.", idiomatic: "Later Chang was enfeoffed as king of Huainan." },
  { zh: "淮南王蚤失母，常附呂后，故孝惠、-{呂后}-時得無患；", literal: "The king of Huainan had early lost his mother and constantly attached himself to the Empress Lü; therefore in the time of Emperor Hui and -{呂后}- he was without trouble;", idiomatic: "The king of Huainan had lost his mother early and clung to the Empress Lü; therefore under Emperor Hui and -{呂后}- he came to no harm;" },
  { zh: "而常心怨辟陽侯，以為不強爭之於-{呂后}-，使其母恨而死也。", literal: "yet he constantly resented the Marquis of Piyang in his heart, holding that he had not strongly contended for him before -{呂后}-, so that his mother died in hatred.", idiomatic: "yet he always resented the Marquis of Piyang, believing he had not pressed his case hard enough before -{呂后}-, so that his mother died in bitterness." },
  { zh: "及帝即位，淮南王自以最親，驕蹇，數不奉法；", literal: "When the emperor took the throne, the king of Huainan, deeming himself the closest kin, was arrogant and obstinate and repeatedly failed to obey the law;", idiomatic: "When the emperor took the throne, the king of Huainan, deeming himself the closest kin, grew arrogant and obstinate and repeatedly defied the law;" },
  { zh: "上常寬假之。", literal: "the emperor constantly showed him leniency.", idiomatic: "the emperor constantly indulged him." },
  { zh: "是歲，入朝，從上入苑囿獵，與上同車，常謂上「大兄」。", literal: "This year he came to court, followed the emperor into the park to hunt, rode in the same carriage with him, and constantly called the emperor \"Elder Brother.\"", idiomatic: "That year he came to court, followed the emperor into the parklands to hunt, rode in the same carriage with him, and habitually called the emperor \"Elder Brother.\"" },
  { zh: "王有材力，能扛鼎。", literal: "The king had strength and could shoulder a cauldron.", idiomatic: "The king was powerfully built and could shoulder a cauldron." },
  { zh: "乃往見辟陽侯，自袖鐵椎椎辟陽侯，令從者魏敬剄之；", literal: "He then went to see the Marquis of Piyang, drew an iron mallet from his sleeve and struck the Marquis of Piyang, and ordered his follower Wei Jing to cut off his head;", idiomatic: "He then went to see the Marquis of Piyang, drew an iron mallet from his sleeve and struck him down, and ordered his follower Wei Jing to cut off his head;" },
  { zh: "馳走闕下，肉袒謝罪。", literal: "he galloped to the palace gate, bared his torso, and begged forgiveness.", idiomatic: "he galloped to the palace gate, bared his torso, and begged forgiveness." },
  { zh: "帝傷其志為親，故赦弗治。", literal: "The emperor was moved by his intent on behalf of kin and therefore pardoned him without prosecution.", idiomatic: "The emperor was moved by his devotion to kin and pardoned him without prosecution." },
  { zh: "當是時，薄太后及太子、諸大臣皆憚淮南王。", literal: "At that time Empress Dowager Bo, the crown prince, and all the great ministers feared the king of Huainan.", idiomatic: "At that time Empress Dowager Bo, the crown prince, and all the great ministers feared the king of Huainan." },
  { zh: "淮南王以此，歸國益驕恣，出入稱警蹕，稱制擬於天子。", literal: "The king of Huainan for this reason, on returning to his state, grew all the more arrogant and unrestrained; going out and coming in he proclaimed imperial escort and styled his commands like the Son of Heaven.", idiomatic: "Because of this, on returning to his state the king of Huainan grew all the more arrogant and unrestrained; when he went abroad he proclaimed imperial escort and styled his commands like the Son of Heaven." },
  { zh: "袁盎諫曰：「諸侯太驕，必生患。", literal: "Yuan Ang remonstrated, saying: \"If the feudal lords are too arrogant, trouble will surely arise.", idiomatic: "Yuan Ang remonstrated, \"If the feudal lords grow too arrogant, trouble will surely follow." },
  { zh: "」上不聽。", literal: "\" The emperor did not heed him.", idiomatic: "\" The emperor did not heed him." },
  { zh: "----6五月，匈奴右賢王入居河南地，侵盜上郡保塞蠻夷，殺略人民。", literal: "----6 In the fifth month, the Xiongnu Right Worthy King entered and occupied the lands south of the river, raided and plundered the fortified passes of Shang commandery and the frontier barbarians, and killed and carried off the people.", idiomatic: "----6 In the fifth month, the Xiongnu Right Worthy King crossed into the lands south of the river, raided the fortified passes of Shang commandery and the frontier tribes, and killed and carried off the people." },
  { zh: "上幸甘泉。", literal: "The emperor visited Ganquan.", idiomatic: "The emperor went to Ganquan." },
  { zh: "遣丞相灌嬰發車騎八萬五千，詣高奴擊右賢王；", literal: "He sent the chancellor Guan Ying to mobilize eighty-five thousand chariots and horsemen to proceed to Gaonu and strike the Right Worthy King;", idiomatic: "He sent Chancellor Guan Ying to mobilize eighty-five thousand chariots and horsemen to Gaonu to strike the Right Worthy King;" },
  { zh: "發中尉材官屬衛將軍，軍長安。", literal: "he mobilized the skilled soldiers under the commandant of the center to serve the Defender-General and garrison Chang'an.", idiomatic: "he mobilized the commandant of the center's skilled soldiers under the Defender-General to garrison Chang'an." },
  { zh: "右賢王走出塞。", literal: "The Right Worthy King fled beyond the passes.", idiomatic: "The Right Worthy King fled beyond the frontier." },
  { zh: "----7上自甘泉之高奴，因幸太原，見故群臣，皆賜之；", literal: "----7 The emperor, from Ganquan to Gaonu, then visited Taiyuan, saw his former ministers, and all were rewarded;", idiomatic: "----7 The emperor, traveling from Ganquan to Gaonu, then visited Taiyuan, saw his former ministers, and rewarded them all;" },
  { zh: "復晉陽、中都民三歲租。", literal: "he remitted three years' rent for the people of Jinyang and Zhongdu.", idiomatic: "he remitted three years' rent for the people of Jinyang and Zhongdu." },
  { zh: "留游太原十餘日。", literal: "He lingered and toured Taiyuan for more than ten days.", idiomatic: "He lingered in Taiyuan for more than ten days." },
  { zh: "----8初，大臣之誅諸呂也，朱虛侯功尤大。", literal: "----8 At the outset, when the great ministers executed the various Lü, the merit of the Marquis of Zhuwei was especially great.", idiomatic: "----8 At the outset, when the great ministers destroyed the Lü clan, the Marquis of Zhuwei's merit was especially great." },
  { zh: "大臣許盡以趙地王朱虛侯，盡以梁地王東牟侯。", literal: "The great ministers had promised to make the Marquis of Zhuwei king of Zhao in full and the Marquis of Dongmou king of Liang in full.", idiomatic: "The great ministers had promised to make the Marquis of Zhuwei king of Zhao in full and the Marquis of Dongmou king of Liang in full." },
  { zh: "及帝立，聞朱虛、東牟之初欲立齊王，故絀其功，及王諸子，乃割齊二郡以王之。", literal: "When the emperor was installed, hearing that Zhuwei and Dongmou at first had wished to install the king of Qi, he therefore reduced their merit; when he enfeoffed his sons as kings, he only carved off two commanderies of Qi to make them kings.", idiomatic: "When the emperor was installed, learning that Zhuwei and Dongmou had at first wished to install the king of Qi, he reduced their rewards; when he enfeoffed his sons as kings, he carved off only two commanderies of Qi for them." },
  { zh: "興居自以失職奪功，頗怏怏；", literal: "Xingju himself held that he had lost his post and been robbed of merit and was quite discontent;", idiomatic: "Xingju felt he had lost his post and been robbed of his due reward, and was deeply discontent;" },
  { zh: "聞帝幸太原，以為天子且自擊胡，遂發兵反。", literal: "hearing that the emperor was visiting Taiyuan, he supposed the Son of Heaven was about to strike the barbarians himself, and therefore raised troops in revolt.", idiomatic: "hearing that the emperor was visiting Taiyuan, he supposed the Son of Heaven was about to strike the barbarians in person, and raised troops in revolt." },
  { zh: "帝聞之，罷丞相及行兵皆歸長安，以棘浦侯柴武為大將軍，將四將軍、十萬眾擊之；", literal: "When the emperor heard it, he dismissed the chancellor and recalled the marching troops to Chang'an, made the Marquis of Jipo Chai Wu grand general, and led four generals and a hundred thousand men to strike him;", idiomatic: "When the emperor heard it, he recalled the chancellor and all marching troops to Chang'an, made the Marquis of Jipo Chai Wu grand general, and sent four generals with a hundred thousand men against him;" },
  { zh: "祁侯繒賀為將軍，軍滎陽。", literal: "the Marquis of Qi He was made general and encamped at Xingyang.", idiomatic: "the Marquis of Qi He was made general and encamped at Xingyang." },
  { zh: "秋，七月，上自太原至長安。", literal: "In autumn, the seventh month, the emperor came from Taiyuan to Chang'an.", idiomatic: "In autumn, the seventh month, the emperor returned from Taiyuan to Chang'an." },
  { zh: "詔：「濟北吏民，兵未至先自定及以軍城邑降者，皆赦之，復官爵；", literal: "An edict: \"The officials and people of Jibei who before the army arrived had already settled themselves of their own accord or surrendered cities and towns with their forces—all are pardoned and restored in office and rank;", idiomatic: "An edict: \"The officials and people of Jibei who before the army arrived had already settled matters themselves or surrendered cities and towns—all are pardoned and restored in office and rank;" },
  { zh: "與王興居去來者，赦之。", literal: "those who went and came with King Xingju are pardoned.\"", idiomatic: "those who went and came with King Xingju are pardoned.\"" },
  { zh: "」八月，濟北王興居兵敗，自殺。", literal: "\" In the eighth month, King Xingju of Jibei's troops were defeated and he killed himself.", idiomatic: "\" In the eighth month, King Xingju of Jibei's troops were defeated and he killed himself." },
  { zh: "----9初，南陽張釋之為騎郎，十年不得調，欲免歸。", literal: "----9 At the outset, Zhang Shizhi of Nanyang served as a cavalry gentleman of the palace; ten years without promotion, he wished to resign and return home.", idiomatic: "----9 At the outset, Zhang Shizhi of Nanyang served as a cavalry gentleman of the palace; after ten years without promotion he wished to resign and go home." },
  { zh: "袁盎知其賢而薦之，為謁者僕射。", literal: "Yuan Ang knew his worth and recommended him; he was made usher and master of attendants.", idiomatic: "Yuan Ang knew his worth and recommended him; he was made usher and master of attendants." },
  { zh: "釋之從行，登虎圈，上問上林尉諸禽獸簿。", literal: "Shizhi followed on the journey; they ascended the tiger enclosure, and the emperor questioned the superintendent of the Shanglin park on the registers of the various birds and beasts.", idiomatic: "Shizhi accompanied the journey; they ascended the tiger enclosure, and the emperor questioned the superintendent of the Shanglin park on the registers of birds and beasts." },
  { zh: "十餘問，尉左右視，盡不能對。", literal: "After more than ten questions the superintendent looked left and right; none could he answer.", idiomatic: "After more than ten questions the superintendent looked about; he could answer none of them." },
  { zh: "虎圈嗇夫從旁代尉對。", literal: "The chief of the tiger enclosure answered from the side in place of the superintendent.", idiomatic: "The chief of the tiger enclosure answered from the side in the superintendent's stead." },
  { zh: "上所問禽獸簿甚悉，欲以觀其能；", literal: "What the emperor asked about the registers of birds and beasts was very thorough; he wished thereby to observe his ability;", idiomatic: "The emperor's questions on the registers were very thorough; he wished to test the man's ability;" },
  { zh: "口對響應，無窮者。", literal: "he answered by mouth in echoing response, without end.", idiomatic: "the man answered fluently, without end." },
  { zh: "帝曰：「吏不當若是邪！", literal: "The emperor said: \"Should an officer not be like this!", idiomatic: "The emperor said, \"Should an officer not be like this!" },
  { zh: "尉無賴！", literal: "The superintendent is worthless!", idiomatic: "The superintendent is worthless!" },
  { zh: "」乃詔釋之拜嗇夫為上林令。", literal: "\" He then ordered Shizhi to invest the chief as superintendent of Shanglin.", idiomatic: "\" He then ordered Shizhi to invest the chief as superintendent of Shanglin." },
  { zh: "釋之久之前，曰：「陛下以絳侯周勃何如人也？", literal: "Shizhi advanced and stood long before him, saying: \"Your Majesty, what sort of man do you hold the Marquis of Jiang Zhou Bo to be?", idiomatic: "Shizhi stepped forward and said, \"Your Majesty, what sort of man do you hold the Marquis of Jiang Zhou Bo to be?" },
  { zh: "」上曰：「長者也。", literal: "\" The emperor said: \"A man of worth.", idiomatic: "\" The emperor said, \"A man of worth." },
  { zh: "」又復問：「東陽侯張相如何如人也？", literal: "\" He again asked: \"What sort of man is the Marquis of Dongyang Zhang Xiang?", idiomatic: "\" He asked again, \"What sort of man is the Marquis of Dongyang Zhang Xiang?" },
  { zh: "」上復曰：「長者。", literal: "\" The emperor again said: \"A man of worth.", idiomatic: "\" The emperor again said, \"A man of worth." },
  { zh: "」釋之曰：「夫絳侯、東陽侯稱為長者，此兩人言事曾不能出口，豈效此嗇夫喋喋利口捷給哉！", literal: "\" Shizhi said: \"The Marquis of Jiang and the Marquis of Dongyang are called men of worth—yet these two men, when speaking of affairs, could not get a word out; how could one imitate this chief's clattering, sharp-tongued quick replies!", idiomatic: "\" Shizhi said, \"The Marquis of Jiang and the Marquis of Dongyang are called men of worth—yet these two could scarcely get a word out when speaking of affairs. How could one imitate this chief's clattering, sharp-tongued quick replies!" },
  { zh: "且秦以任刀筆之吏，爭以亟疾苛察相高。", literal: "Moreover Qin employed clerks with knife and brush; they vied to set one another high in haste, severity, and minute scrutiny.", idiomatic: "Moreover Qin put its trust in clerks with knife and brush; they vied to outdo one another in haste, severity, and petty scrutiny." },
  { zh: "其敝，徒文具而無實，不聞其過，陵遲至於土崩。", literal: "Its harm was that there was only paper show without substance, faults went unheard, and decline dragged on until the realm collapsed.", idiomatic: "The harm was empty paperwork without substance, faults went unheard, and decline dragged on until the realm collapsed." },
  { zh: "今陛下以嗇夫口辨而超遷之，臣恐天下隨風而靡，爭為口辨而無其實。", literal: "Now Your Majesty would promote this chief for glib speech—I fear all under Heaven would follow the wind and strive for glib speech without substance.", idiomatic: "Now Your Majesty would promote this chief for glib speech—I fear the realm would follow the wind and strive for glib speech without substance." },
  { zh: "夫下之化上，疾於景響，舉錯不可不審也。", literal: "How the lower transforms to the upper is swifter than shadow to sound; what is raised and set down cannot go unexamined.\"", idiomatic: "How the lower transforms to match the upper is swifter than shadow to echo; what you raise and set down cannot go unexamined.\"" },
  { zh: "」帝曰：「善！", literal: "\" The emperor said: \"Well said!", idiomatic: "\" The emperor said, \"Well said!" },
  { zh: "」乃不拜嗇夫。", literal: "\" He then did not invest the chief.", idiomatic: "\" He then did not invest the chief." },
  { zh: "上就車，詔釋之參乘。", literal: "The emperor mounted his carriage and ordered Shizhi to ride beside him as attendant.", idiomatic: "The emperor mounted his carriage and ordered Shizhi to ride beside him as attendant." },
  { zh: "徐行，問釋之秦之敝，具以質言。", literal: "They went slowly, and the emperor asked Shizhi about Qin's harms; he set them forth in full with plain truth.", idiomatic: "They went slowly, and the emperor asked Shizhi about Qin's harms; he laid them out plainly and in full." },
  { zh: "至宮，上拜釋之為公車令。", literal: "On reaching the palace, the emperor invested Shizhi as master of the imperial carriages.", idiomatic: "On reaching the palace, the emperor made Shizhi master of the imperial carriages." },
  { zh: "頃之，太子與梁王共車入朝，不下司馬門。", literal: "Before long the crown prince and the king of Liang entered court in the same carriage and did not dismount at the Gate of the Grand Marshal.", idiomatic: "Before long the crown prince and the king of Liang entered court in the same carriage and did not dismount at the Gate of the Grand Marshal." },
  { zh: "於是釋之追止太子、梁王，無得入殿門，遂劾「不下公門，不敬」，奏之。", literal: "Thereupon Shizhi pursued and halted the crown prince and the king of Liang; they might not enter the hall gate; he then impeached them for \"not dismounting at the public gate—indecorum\" and memorialized it.", idiomatic: "Thereupon Shizhi pursued and halted the crown prince and the king of Liang; they might not enter the hall gate; he impeached them for \"not dismounting at the public gate—indecorum\" and memorialized it." },
  { zh: "薄太后聞之；", literal: "Empress Dowager Bo heard of it;", idiomatic: "Empress Dowager Bo heard of it;" },
  { zh: "帝免冠，謝教兒子不謹。", literal: "the emperor removed his cap and apologized for not having taught his sons with care.", idiomatic: "the emperor removed his cap and apologized for not having taught his sons with sufficient care." },
  { zh: "薄太后乃使使承詔赦太子、梁王，然後得入。", literal: "Empress Dowager Bo then sent an envoy bearing the edict to pardon the crown prince and the king of Liang; only then might they enter.", idiomatic: "Empress Dowager Bo then sent an envoy bearing the edict to pardon the crown prince and the king of Liang; only then could they enter." },
  { zh: "帝由是奇釋之，拜為中大夫；", literal: "The emperor for this reason marveled at Shizhi and invested him as palace grandee;", idiomatic: "The emperor for this reason marveled at Shizhi and made him palace grandee;" },
  { zh: "頃之，至中郎將。", literal: "before long he rose to commandant of the palace guards.", idiomatic: "before long he rose to commandant of the palace guards." },
  { zh: "從行至霸陵，上謂群臣曰：「嗟乎！", literal: "Following on the journey to Baling, the emperor said to the ministers: \"Alas!", idiomatic: "On the journey to Baling, the emperor said to the ministers, \"Alas!" },
  { zh: "以北山石為槨，用紵絮昔斮陳漆其間，豈可動哉！", literal: "to take northern mountain stone for the outer coffin, use ramie floss and old hemp to pack and lay lacquer within—could it be moved!", idiomatic: "to take stone from the northern mountains for the outer coffin, pack it with ramie floss and old hemp and lay lacquer within—who could breach it!" },
  { zh: "」左右皆曰：「善！", literal: "\" Those beside him all said: \"Excellent!", idiomatic: "\" Those beside him all said, \"Excellent!" },
  { zh: "」釋之曰：「使其中有可欲者，雖錮南山猶有隙；", literal: "\" Shizhi said: \"If within there is something to be desired, though the southern mountains were caged there would still be a gap;", idiomatic: "\" Shizhi said, \"If within there is something to be desired, though you caged the southern mountains there would still be a gap;" },
  { zh: "使其中無可欲者，雖無石槨，又何戚焉！", literal: "if within there is nothing to be desired, though there were no stone coffin, what sorrow would there be!\"", idiomatic: "if within there is nothing to be desired, though there were no stone coffin, what would there be to grieve over!\"" },
  { zh: "」帝稱善。", literal: "\" The emperor praised it as well said.", idiomatic: "\" The emperor praised it as well said." },
  { zh: "是歲，釋之為廷尉。", literal: "This year Shizhi became minister of justice.", idiomatic: "That year Shizhi became minister of justice." },
  { zh: "上行出中渭橋，有一人從橋下走，乘輿馬驚。", literal: "The emperor was traveling out past the Zhongwei Bridge when a man ran out from beneath the bridge and the imperial carriage horses were startled.", idiomatic: "The emperor was traveling past the Zhongwei Bridge when a man ran out from beneath the bridge and the imperial carriage horses were startled." },
  { zh: "於是使騎捕之，屬廷尉。", literal: "He then sent horsemen to seize him and handed him over to the minister of justice.", idiomatic: "He sent horsemen to seize him and handed him over to the minister of justice." },
  { zh: "釋之奏當：「此人犯蹕，當罰金。", literal: "Shizhi memorialized the proper sentence: \"This man violated the imperial progress and should be fined in gold.\"", idiomatic: "Shizhi memorialized the proper sentence: \"This man violated the imperial progress and should be fined in gold.\"" },
  { zh: "」上怒曰：「此人親驚吾馬，馬賴和柔，令它馬，固不敗傷我乎！", literal: "\" The emperor was enraged and said: \"This man personally startled my horses; the horses luckily were gentle—had they been other horses, would they not surely have thrown and injured me!", idiomatic: "\" The emperor was enraged and said, \"This man personally startled my horses; the horses were luckily gentle—had they been other horses, would they not surely have thrown and injured me!" },
  { zh: "而廷尉乃當之罰金。", literal: "Yet the minister of justice sets the penalty at a fine in gold.", idiomatic: "Yet the minister of justice sets the penalty at a fine in gold." },
  { zh: "」釋之曰：「法者，天下公共也。", literal: "\" Shizhi said: \"Law is what is shared in common by all under Heaven.", idiomatic: "\" Shizhi said, \"Law is what all under Heaven share in common." },
  { zh: "今法如是，更重之，是法不信於民也。", literal: "Now the law is thus; if it were made heavier, that would be law not believed by the people.", idiomatic: "Now the law is thus; if it were made heavier, the law would no longer be believed by the people." },
  { zh: "且方其時，上使使誅之則已。", literal: "Moreover at that very moment, had Your Majesty sent an envoy to execute him, it would have been done.", idiomatic: "Moreover at that very moment, had Your Majesty sent an envoy to execute him, it would have been done." },
  { zh: "今已下廷尉。", literal: "Now he has already been handed down to the minister of justice.", idiomatic: "Now he has already been handed down to the minister of justice." },
  { zh: "廷尉，天下之平也，壹傾，天下用法皆為之輕重，民安所錯其手足！", literal: "The minister of justice is the balance of all under Heaven; once it tilts, all under Heaven in applying the law will make it light or heavy for themselves—where will the people place their hands and feet!", idiomatic: "The minister of justice is the balance of all under Heaven; once it tilts, everyone in applying the law will bend it to their own ends—where will the people place their hands and feet!" },
  { zh: "唯陛下察之。", literal: "I beg Your Majesty to examine this.\"", idiomatic: "I beg Your Majesty to examine this.\"" },
  { zh: "」上良久曰：「廷尉當是也。", literal: "\" After a long while the emperor said: \"The minister of justice's sentence is correct.", idiomatic: "\" After a long while the emperor said, \"The minister of justice's sentence is correct." },
  { zh: "其後人有盜高廟坐前玉環，得；", literal: "Afterward someone stole the jade ring before the seat in the High Ancestor's temple and was captured;", idiomatic: "Afterward someone stole the jade ring before the seat in the High Ancestor's temple and was captured;" },
  { zh: "帝怒，下廷尉治。", literal: "the emperor was enraged and handed him down to the minister of justice for prosecution.", idiomatic: "the emperor was enraged and handed him down to the minister of justice for prosecution." },
  { zh: "釋之按「盜宗廟服御物者」為奏當：棄市。", literal: "Shizhi applied the statute \"one who steals vessels and regalia of the ancestral temple\" and memorialized the proper sentence: execution in the marketplace.", idiomatic: "Shizhi applied the statute on stealing vessels and regalia of the ancestral temple and memorialized the proper sentence: execution in the marketplace." },
  { zh: "上大怒曰：「人無道，乃盜先帝器！", literal: "The Emperor was greatly angered and said: \"The man is without the Way—yet he steals the former Emperor's vessels!", idiomatic: "The Emperor was greatly angered and said, \"The man is without principle—yet he steals the former Emperor's vessels!\"" },
  { zh: "吾屬廷尉者，欲致之族；", literal: "I handed him over to the Commandant of Justice intending to bring him to clan extermination;", idiomatic: "I handed him over to the Commandant of Justice intending to have his whole clan executed;" },
  { zh: "而君以法奏之，非吾所以共承宗廟意也。", literal: "yet you, my lord, reported him according to the law—this is not the intent by which we together uphold the ancestral temple.", idiomatic: "yet you, my lord, reported him according to the law—this is not how we together uphold the ancestral temple's intent." },
  { zh: "」釋之免冠頓首謝曰：「法如是，足也。", literal: "\" Zhang Shizhi removed his cap and knocked his head in apology, saying: \"The law is thus—that is enough.", idiomatic: "\" Zhang Shizhi removed his cap and kowtowed in apology, saying, \"The law is thus—that is enough." },
  { zh: "且罪等，然以逆順為差。", literal: "Moreover, though crimes are equal, they are graded by rebellion and compliance.", idiomatic: "Moreover, though crimes may be equal, they are graded by whether they are rebellious or compliant." },
  { zh: "今盜宗廟器而族之，有如萬分一，假令愚民取長陵一抔土，陛下且何以加其法乎？", literal: "Now if one exterminates the clan for stealing temple vessels, suppose one in ten thousand—if foolish commoners took a handful of earth from Changling, how would Your Majesty add to the law against them?", idiomatic: "Now if one exterminates the clan for stealing temple vessels, suppose one in ten thousand—if foolish commoners took a handful of earth from Changling, how would Your Majesty increase the penalty against them?" },
  { zh: "」帝乃白太后許之。", literal: "\" The Emperor thereupon told the Empress Dowager and obtained her assent.", idiomatic: "\" The Emperor thereupon told the Empress Dowager and obtained her assent." },
  { zh: "1冬，十二月，穎陰懿侯灌嬰薨。", literal: "1 In winter, the twelfth month, the Marquis Yi of Yingyin Guan Ying died.", idiomatic: "In winter, the twelfth month, the Marquis Yi of Yingyin Guan Ying died." },
  { zh: "----2春，正月，甲午，以御史大夫陽武張蒼為丞相。", literal: "----2 In spring, the first month, on jiawu, the Grandee Secretary Zhang Cang of Yangwu was made Chancellor.", idiomatic: "----2 In spring, the first month, on jiawu, the Grandee Secretary Zhang Cang of Yangwu was made Chancellor." },
  { zh: "蒼好書，博聞，尤邃律曆。", literal: "Zhang was fond of books, broadly learned, and especially deep in calendrical astronomy.", idiomatic: "Zhang was fond of books, broadly learned, and especially expert in calendrical astronomy." },
  { zh: "----3上召河東守季布，欲以為御史大夫。", literal: "----3 The Emperor summoned the governor of Hedong Ji Bu, wishing to make him Grandee Secretary.", idiomatic: "----3 The Emperor summoned the governor of Hedong Ji Bu, wishing to make him Grandee Secretary." },
  { zh: "有言其勇、使酒、難近者；", literal: "Someone said he was brave, given to drink, and hard to approach;", idiomatic: "Someone said he was brave, given to drink, and hard to approach;" },
  { zh: "至，留邸一月，見罷。", literal: "when he arrived, he was kept at the lodging house a month, then dismissed.", idiomatic: "when he arrived, he was kept at the lodging house a month, then dismissed." },
  { zh: "季布因進曰：「臣無功竊寵，待罪河東，陛下無故召臣，此人必有以臣欺陛下者。", literal: "Ji Bu thereupon advanced and said: \"Your servant, without merit yet enjoying favor, awaits punishment in Hedong; Your Majesty summoned your servant without cause—someone must have used your servant to deceive Your Majesty.", idiomatic: "Ji Bu thereupon advanced and said, \"Your servant, without merit yet enjoying favor, awaits punishment in Hedong; Your Majesty summoned me without cause—someone must have used me to deceive Your Majesty." },
  { zh: "今臣至，無所受事，罷去，此人必有毀臣者。", literal: "Now your servant has come and received no commission, yet is dismissed—someone must have slandered your servant.", idiomatic: "Now I have come and received no commission, yet am dismissed—someone must have slandered me." },
  { zh: "夫陛下以一人之譽而召臣，以一人之毀而去臣，臣恐天下有識聞之，有以窺陛下之淺深也！", literal: "Your Majesty summoned your servant on one man's praise and dismissed your servant on one man's slander; your servant fears that those with understanding throughout the realm, hearing of it, will have a means to gauge Your Majesty's depth and shallowness!", idiomatic: "Your Majesty summoned me on one man's praise and dismissed me on one man's slander; I fear that those with understanding throughout the realm, hearing of it, will gauge Your Majesty's depth and shallowness!\"" },
  { zh: "」上默然，慚，良久曰：「河東，吾股肱郡，故特召君耳。", literal: "\" The Emperor was silent, ashamed; after a long while he said: \"Hedong is my arm-and-thigh district; therefore I specially summoned you, my lord.", idiomatic: "\" The Emperor was silent, ashamed; after a long while he said, \"Hedong is my arm-and-thigh district; therefore I specially summoned you.\"" },
  { zh: "」----4上議以賈誼任公卿之位。", literal: "\" ----4 The Emperor deliberated on appointing Jia Yi to a ministerial post.", idiomatic: "\" ----4 The Emperor deliberated on appointing Jia Yi to a ministerial post." },
  { zh: "大臣多短之曰：「洛陽之人，年少初學，專欲擅權，紛亂諸事。", literal: "Many great ministers spoke against him, saying: \"A man of Luoyang, young and newly learning, who wishes only to monopolize power and throw affairs into confusion.", idiomatic: "Many great ministers spoke against him, saying, \"A man of Luoyang, young and newly learning, who wishes only to monopolize power and throw affairs into confusion.\"" },
  { zh: "」於是天子後亦疏之，不用其議，以為長沙王太傅。", literal: "\" Thereupon the Son of Heaven later also kept him at a distance, did not use his proposals, and made him Grand Tutor to the king of Changsha.", idiomatic: "\" Thereupon the Son of Heaven later also kept him at a distance, did not use his proposals, and made him Grand Tutor to the king of Changsha." },
  { zh: "----5絳侯周勃既就國，每河東守、尉行縣至絳，勃自畏恐誅，常被甲，令家人持兵以見之。", literal: "----5 After the Marquis of Jiang Zhou Bo had gone to his state, whenever the governor or commandant of Hedong on circuit reached Jiang on county rounds, Bo himself feared execution and often wore armor, ordering his household to hold weapons when receiving them.", idiomatic: "----5 After the Marquis of Jiang Zhou Bo had gone to his state, whenever the governor or commandant of Hedong on circuit reached Jiang on county rounds, Bo feared execution and often wore armor, ordering his household to hold weapons when receiving them." },
  { zh: "其後人有上書告勃欲反，下廷尉。", literal: "Afterward someone submitted a memorial accusing Bo of wishing to rebel; the case was sent down to the Commandant of Justice.", idiomatic: "Afterward someone submitted a memorial accusing Bo of wishing to rebel; the case was sent to the Commandant of Justice." },
  { zh: "廷尉逮捕勃，治之。", literal: "The Commandant of Justice arrested Bo and tried him.", idiomatic: "The Commandant of Justice arrested Bo and tried him." },
  { zh: "勃恐，不知置辭。", literal: "Bo was afraid and did not know how to set forth his words.", idiomatic: "Bo was afraid and did not know what to say." },
  { zh: "吏稍侵辱之，勃以千金與獄吏，獄吏乃書牘背示之曰：「以公主為證。", literal: "The clerks gradually insulted and humiliated him; Bo gave a thousand in gold to the prison clerk, and the clerk then wrote on the back of the document slip and showed him, saying: \"Use the princess as witness.", idiomatic: "The clerks gradually insulted and humiliated him; Bo gave a thousand in gold to the prison clerk, and the clerk wrote on the back of the document slip and showed him, saying, \"Use the princess as witness." },
  { zh: "」公主者，帝女也，勃太子勝之尚之。", literal: "\" The princess was the Emperor's daughter; Bo's heir Sheng had married her.", idiomatic: "\" The princess was the Emperor's daughter; Bo's heir Sheng had married her." },
  { zh: "薄太后亦以為勃無反事。", literal: "Empress Dowager Bo also held that Bo had no matter of rebellion.", idiomatic: "Empress Dowager Bo also held that Bo had no rebellious intent." },
  { zh: "帝朝太后，太后以冒絮提帝曰：「絳侯始誅諸呂，綰皇帝璽，將兵於北軍，不以此時反，今居一小縣，顧欲反邪？", literal: "When the Emperor attended the Empress Dowager, she took her padded cap-strings and struck the Emperor, saying: \"The Marquis of Jiang at first executed the Lü clan, held the Emperor's seal, and commanded troops in the Northern Army—he did not rebel then; now dwelling in a small county, would he turn and wish to rebel?", idiomatic: "When the Emperor attended the Empress Dowager, she took her padded cap-strings and struck the Emperor, saying, \"The Marquis of Jiang at first executed the Lü clan, held the Emperor's seal, and commanded troops in the Northern Army—he did not rebel then; now dwelling in a small county, would he turn and rebel?\"" },
  { zh: "」帝既見絳侯獄辭，乃謝曰：「吏方驗而出之。", literal: "\" The Emperor, having seen the Marquis of Jiang's prison statement, then apologized, saying: \"The clerks are just now verifying and will release him.", idiomatic: "\" The Emperor, having seen the Marquis of Jiang's prison statement, then apologized, saying, \"The clerks are just now verifying and will release him.\"" },
  { zh: "」於是使使持節赦絳侯，復爵邑。", literal: "\" Thereupon he sent an envoy bearing credentials to pardon the Marquis of Jiang and restore his rank and fief.", idiomatic: "\" Thereupon he sent an envoy bearing credentials to pardon the Marquis of Jiang and restore his rank and fief." },
  { zh: "絳侯既出，曰：「吾嘗將百萬軍，然安知獄吏之貴乎！", literal: "Once the Marquis of Jiang was out, he said: \"I once commanded a million troops—yet how did I know the prison clerk's exalted station!", idiomatic: "Once the Marquis of Jiang was out, he said, \"I once commanded a million troops—yet how did I know the prison clerk's exalted station!\"" },
  { zh: "」----6作顧成廟。", literal: "\" ----6 The Gu Cheng temple was built.", idiomatic: "\" ----6 The Gu Cheng temple was built." },
  { zh: "----1春，二月，地震。", literal: "----1 In spring, the second month, there was an earthquake.", idiomatic: "----1 In spring, the second month, there was an earthquake." },
  { zh: "----2初，秦用半兩錢，高祖嫌其重，難用，更鑄莢錢。", literal: "----2 At first Qin used banliang coins; High Emperor found them heavy and hard to use and recast elm-seed coins.", idiomatic: "----2 At first Qin used banliang coins; the High Emperor found them heavy and hard to use and recast elm-seed coins." },
  { zh: "於是物價騰踴，米至石萬錢。", literal: "Thereupon prices soared; rice reached ten thousand cash per picul.", idiomatic: "Thereupon prices soared; rice reached ten thousand cash per picul." },
  { zh: "夏，四月，更造四銖錢，除盜鑄錢令，使民得自鑄。", literal: "In summer, the fourth month, four-zhu coins were newly cast; the statute against illicit coinage was removed and the people were allowed to cast for themselves.", idiomatic: "In summer, the fourth month, four-zhu coins were newly cast; the statute against illicit coinage was removed and the people were allowed to cast coins themselves." },
  { zh: "賈誼諫曰：「法使天下公得雇租鑄銅、錫為錢，敢雜以鉛、鐵為它巧者，其罪黥。", literal: "Jia Yi remonstrated, saying: \"The law allows all under Heaven publicly to hire out rent and cast copper and tin into coins; whoever dares to mix in lead or iron for other tricks—the crime is tattooing.", idiomatic: "Jia Yi remonstrated, saying, \"The law allows all under Heaven publicly to hire out rent and cast copper and tin into coins; whoever dares to mix in lead or iron for other tricks—the penalty is tattooing." },
  { zh: "然鑄錢之情，非殽雜為巧，則不可得贏；", literal: "Yet the disposition of those who cast coins—unless they adulterate for trickery—cannot obtain profit;", idiomatic: "Yet those who cast coins, unless they adulterate for trickery, cannot obtain profit;" },
  { zh: "而殽之甚微，為利其厚。", literal: "and though the adulteration is very slight, the profit is very thick.", idiomatic: "and though the adulteration is very slight, the profit is very great." },
  { zh: "夫事有召禍而法有起奸；", literal: "Affairs have that which summons disaster, and laws have that which raises villainy;", idiomatic: "Affairs have that which summons disaster, and laws have that which raises villainy;" },
  { zh: "今令細民人操造幣之勢，各隱屏而鑄作，因欲禁其厚利微奸，雖黥罪日報，其勢不止。", literal: "now the order lets petty people grasp the power to make currency, each hiding behind screens and casting—yet one wishes to forbid their thick profit and slight villainy; though tattooing crimes are reported daily, the trend does not stop.", idiomatic: "now the order lets petty people grasp the power to make currency, each hiding behind screens and casting—yet one wishes to forbid their great profit and slight fraud; though tattooing penalties are reported daily, the trend does not stop." },
  { zh: "乃者，民人抵罪多者一縣百數，及吏之所疑搒笞奔走者甚眾。", literal: "Recently, among the people convicted, in many counties the number reaches the hundreds, and those whom officials suspect, beat with the bastinado, and chase about are very numerous.", idiomatic: "Recently, among the people convicted, in many counties the number reaches the hundreds, and those whom officials suspect, beat with the bastinado, and chase about are very numerous." },
  { zh: "夫縣法以誘民，使入隱阱，孰多於此！", literal: "To set up the law to lure the people and make them enter hidden pits—what exceeds this!", idiomatic: "To set up the law to lure the people and make them fall into traps—what exceeds this!" },
  { zh: "又民用錢，郡縣不同：或用輕錢，百加若干；", literal: "Moreover, in the people's use of money, commanderies and counties differ: some use light coins, adding so many per hundred;", idiomatic: "Moreover, in the people's use of money, commanderies and counties differ: some use light coins, adding so many per hundred;" },
  { zh: "或用重錢，平稱不受。", literal: "some use heavy coins, and level weighing is not accepted.", idiomatic: "some use heavy coins, and level weighing is not accepted." },
  { zh: "法錢不立，吏急而壹之乎？", literal: "If the statutory coin is not established, shall officials press urgently to unify them?", idiomatic: "If the statutory coin is not established, shall officials press urgently to unify them?" },
  { zh: "則大為煩苛而力不能勝；", literal: "Then there will be great vexation and severity, yet strength cannot overcome it;", idiomatic: "Then there will be great vexation and severity, yet strength cannot overcome it;" },
  { zh: "縱而弗呵乎？", literal: "or if one indulges and does not rebuke them?", idiomatic: "or if one indulges and does not rebuke them?" },
  { zh: "則市肆異用，錢文大亂；", literal: "then markets and shops use different standards and coin inscriptions are greatly confused;", idiomatic: "then markets and shops use different standards and coin inscriptions are greatly confused;" },
  { zh: "苟非其術，何鄉而可哉！", literal: "if it is not the right method, in what direction can one go!", idiomatic: "if it is not the right method, in what direction can one go!" },
  { zh: "今農事棄捐而采銅者日蕃，釋其耒耨，冶熔炊炭；", literal: "Now farming is abandoned while those who gather copper daily multiply; they set aside plow and hoe, smelt and boil charcoal;", idiomatic: "Now farming is abandoned while those who gather copper daily multiply; they set aside plow and hoe, smelt and boil charcoal;" },
  { zh: "奸錢日多，五穀不為多。", literal: "villainous coin daily increases, and the five grains are not considered abundant.", idiomatic: "illicit coin daily increases, and the five grains are not considered abundant." },
  { zh: "善人怵而為奸邪，願民陷而之刑戮；", literal: "Good men are startled into villainy, and willing people fall into punishments and execution;", idiomatic: "Good men are startled into villainy, and willing people fall into punishments and execution;" },
  { zh: "刑戮將甚不詳，奈何而忽！", literal: "punishments and executions will be very inauspicious—how can one neglect this!", idiomatic: "punishments and executions will be very inauspicious—how can one neglect this!" },
  { zh: "國知患此，吏議必曰『禁之』。", literal: "When the state knows this trouble, officials in council will surely say 'Forbid it.'", idiomatic: "When the state knows this trouble, officials in council will surely say 'Forbid it.'" },
  { zh: "禁之不得其術，其傷必大。", literal: "To forbid it without the right method—the harm must be great.", idiomatic: "To forbid it without the right method—the harm must be great." },
  { zh: "令禁鑄錢，則錢必重；", literal: "If one orders a ban on casting coins, then coins must become heavy;", idiomatic: "If one orders a ban on casting coins, then coins must become heavy;" },
  { zh: "重則其利深，盜鑄如雲而起，棄市之罪又不足以禁矣。", literal: "when heavy, their profit is deep; illicit casting rises like clouds, and the crime of exposure in the market is again not enough to forbid it.", idiomatic: "when heavy, their profit is deep; illicit casting rises like clouds, and the crime of exposure in the market is again not enough to forbid it." },
  { zh: "奸數不勝而法禁數潰，銅使之然也。", literal: "Villainy cannot be overcome while legal prohibitions repeatedly break down—copper makes it so.", idiomatic: "Villainy cannot be overcome while legal prohibitions repeatedly break down—copper makes it so." },
  { zh: "銅佈於天下，其為禍博矣，故不如收之。", literal: "Copper spread through all under Heaven—its harm is broad; therefore it is better to take it back.", idiomatic: "Copper spread through all under Heaven—its harm is broad; therefore it is better to take it back.\"" },
  { zh: "」賈山亦上書諫，以為：「錢者，亡用器也，而可以易富貴。", literal: "\" Jia Shan also submitted a memorial remonstrating, holding: \"Coin is a useless vessel, yet it can be exchanged for wealth and honor.", idiomatic: "\" Jia Shan also submitted a memorial remonstrating, holding, \"Coin is a useless vessel, yet it can be exchanged for wealth and honor." },
  { zh: "富貴者，人主之操柄也；", literal: "Wealth and honor are the sovereign's handle of control;", idiomatic: "Wealth and honor are the sovereign's handle of control;" },
  { zh: "令民為之，是與人主共操柄，不可長也。", literal: "to let the people make it is to share the handle of control with the sovereign—it cannot be long endured.", idiomatic: "to let the people make it is to share the handle of control with the sovereign—it cannot be long endured.\"" },
  { zh: "」上不聽。", literal: "\" The Emperor did not heed them.", idiomatic: "\" The Emperor did not heed them." },
  { zh: "是時，太中大夫鄧通方寵幸，上欲其富，賜之蜀嚴道銅山，使鑄錢。", literal: "At this time the Grand Master of the Palace Deng Tong was in favor; the Emperor wished him to be rich and granted him the copper mountain of Yandao in Shu, letting him cast coins.", idiomatic: "At this time the Grand Master of the Palace Deng Tong was in favor; the Emperor wished him to be rich and granted him the copper mountain of Yandao in Shu, letting him cast coins." },
  { zh: "吳王濞有豫章銅山，招致天下亡命者以鑄錢；", literal: "King Wu of Wu Liu Pi had the copper mountain of Yuzhang and gathered fugitives from all under Heaven to cast coins;", idiomatic: "King Wu of Wu Liu Pi had the copper mountain of Yuzhang and gathered fugitives from all under Heaven to cast coins;" },
  { zh: "東煮海水為鹽；", literal: "eastward he boiled sea water for salt;", idiomatic: "eastward he boiled sea water for salt;" },
  { zh: "以故無賦而國用饒足。", literal: "for this reason without levies the state's expenditure was ample.", idiomatic: "for this reason without levies the state's expenditure was ample." },
  { zh: "於是吳、鄧錢布天下。", literal: "Thereupon Wu and Deng coins spread through all under Heaven.", idiomatic: "Thereupon Wu and Deng coins spread through all under Heaven." },
  { zh: "----3初，帝分代為二國，立皇子武為代王，參為太原王。", literal: "----3 At first the Emperor divided Dai into two states, installing his son Wu as king of Dai and Can as king of Taiyuan.", idiomatic: "----3 At first the Emperor divided Dai into two states, installing his son Wu as king of Dai and Can as king of Taiyuan." },
  { zh: "是歲，徙代王武為淮陽王；", literal: "This year the king of Dai Wu was moved to be king of Huaiyang;", idiomatic: "This year the king of Dai Wu was moved to be king of Huaiyang;" },
  { zh: "以太原王參為代王，盡得故地。", literal: "the king of Taiyuan Can was made king of Dai and fully received the former territory.", idiomatic: "the king of Taiyuan Can was made king of Dai and fully received the former territory." },
  { zh: "----1冬，十月，桃、李華。", literal: "----1 In winter, the tenth month, peach and plum blossomed.", idiomatic: "----1 In winter, the tenth month, peach and plum blossomed." },
  { zh: "----2淮南厲王長自作法令行於其國，逐漢所置吏，請自置相、二千石；", literal: "----2 King Li of Huainan Liu Chang himself made laws and executed them in his state, expelled Han-appointed officials, and requested to appoint his own chancellor and officials at two thousand dan;", idiomatic: "----2 King Li of Huainan Liu Chang himself made laws and executed them in his state, expelled Han-appointed officials, and requested to appoint his own chancellor and officials at two thousand dan;" },
  { zh: "帝曲意從之。", literal: "the Emperor bent his intent and assented.", idiomatic: "the Emperor bent his intent and assented." },
  { zh: "又擅刑殺不辜及爵人至關內侯；", literal: "He also on his own authority punished and killed the innocent and ennobled men up to marquis within the passes;", idiomatic: "He also on his own authority punished and killed the innocent and ennobled men up to marquis within the passes;" },
  { zh: "數上書不遜順。", literal: "repeatedly submitted memorials that were not deferential and compliant.", idiomatic: "repeatedly submitted memorials that were not deferential and compliant." },
  { zh: "帝重自切責之，乃令薄昭與書風諭之，引管、蔡及代頃王、濟北王興居以為儆戒。", literal: "The Emperor heavily reproached himself and then ordered Bo Zhao to write a letter admonishing him, citing Guan and Cai and the kings of Dai Qing, Jibei, and Xingju as warnings.", idiomatic: "The Emperor heavily reproached him and then ordered Bo Zhao to write a letter admonishing him, citing Guan and Cai and the kings of Dai Qing, Jibei, and Xingju as warnings." },
  { zh: "王不說，令大夫但、士伍開章等七十人與棘蒲侯柴武太子奇謀以輦車四十乘反谷口；", literal: "The king was displeased and ordered the grandee Dan, commoner Kai Zhang, and seventy others together with the heir of the Marquis of Jipu Chai Wu, Qi, to plot with forty chariots of the imperial train to rebel at Gukou;", idiomatic: "The king was displeased and ordered the grandee Dan, commoner Kai Zhang, and seventy others together with the heir of the Marquis of Jipu Chai Wu, Qi, to plot with forty chariots of the imperial train to rebel at Gukou;" },
  { zh: "令人使閩越、匈奴。", literal: "he sent men as envoys to Minyue and the Xiongnu.", idiomatic: "he sent men as envoys to Minyue and the Xiongnu." },
  { zh: "事覺，有司治之。", literal: "The affair was discovered and the relevant offices tried it.", idiomatic: "The affair was discovered and the relevant offices tried it." },
  { zh: "使使召淮南王。", literal: "Envoys were sent to summon the king of Huainan.", idiomatic: "Envoys were sent to summon the king of Huainan." },
  { zh: "王至長安，丞相張蒼、典客馮敬行御史大夫事，與宗正、廷尉奏：「長罪當棄市。", literal: "When the king reached Chang'an, Chancellor Zhang Cang and the Director of Guests Feng Jing acting as Grandee Secretary, together with the Director of the Imperial Clan and the Commandant of Justice, memorialized: \"Chang's crime warrants exposure in the market.", idiomatic: "When the king reached Chang'an, Chancellor Zhang Cang and the Director of Guests Feng Jing acting as Grandee Secretary, together with the Director of the Imperial Clan and the Commandant of Justice, memorialized, \"Chang's crime warrants exposure in the market.\"" },
  { zh: "」制曰：「其赦長死罪，廢，勿王；", literal: "\" The rescript said: \"Pardon Chang's capital crime; depose him—do not let him remain king;", idiomatic: "\" The rescript said, \"Pardon Chang's capital crime; depose him—do not let him remain king;" },
  { zh: "徙處蜀郡嚴道邛郵。", literal: "banish him to Qiongdu in Yandao of Shu commandery.", idiomatic: "banish him to Qiongdu in Yandao of Shu commandery.\"" },
  { zh: "」盡誅所與謀者。", literal: "\" All who plotted with him were executed.", idiomatic: "\" All who plotted with him were executed." },
  { zh: "載長以輜車，令縣以次傳之。", literal: "Chang was carried in a supply cart; counties were ordered to relay him in sequence.", idiomatic: "Chang was carried in a supply cart; counties were ordered to relay him in sequence." },
  { zh: "袁盎諫曰：「上素驕淮南王，弗為置嚴傅、相，以故至此。", literal: "Yuan Ang remonstrated, saying: \"Your Majesty has always indulged the king of Huainan and did not appoint a strict tutor and chancellor; for this reason it has come to this.", idiomatic: "Yuan Ang remonstrated, saying, \"Your Majesty has always indulged the king of Huainan and did not appoint a strict tutor and chancellor; for this reason it has come to this." },
  { zh: "淮南王為人剛，今暴摧折之，臣恐卒逢霧露病死，陛下有殺弟之名，奈何？", literal: "The king of Huainan is by nature stern; now if he is suddenly broken and bent, your servant fears he may in the end meet mist and dew and die of illness—Your Majesty would have the name of killing a younger brother; what is to be done?", idiomatic: "The king of Huainan is by nature stern; now if he is suddenly broken and bent, I fear he may in the end meet mist and dew and die of illness—Your Majesty would have the name of killing a younger brother; what is to be done?\"" },
  { zh: "」上曰：「吾特苦之耳，今復之。", literal: "\" The Emperor said: \"I only meant to distress him; now I restore him.", idiomatic: "\" The Emperor said, \"I only meant to distress him; now I restore him.\"" },
  { zh: "淮南王果憤恚不食死。", literal: "The king of Huainan indeed died of rage and resentment from refusing food.", idiomatic: "The king of Huainan indeed died of rage and resentment from refusing food." },
  { zh: "縣傳至雍，雍令發封，以死聞。", literal: "When the relay reached Yong, the magistrate of Yong broke the seal and reported the death.", idiomatic: "When the relay reached Yong, the magistrate of Yong broke the seal and reported the death." },
  { zh: "上哭甚悲，謂袁盎曰：「吾不聽公言，卒亡淮南王！", literal: "The Emperor wept very bitterly and said to Yuan Ang: \"I did not heed your words and in the end lost the king of Huainan!", idiomatic: "The Emperor wept very bitterly and said to Yuan Ang, \"I did not heed your words and in the end lost the king of Huainan!" },
  { zh: "今為奈何？", literal: "Now what is to be done?", idiomatic: "Now what is to be done?\"" },
  { zh: "」盎曰：「獨斬丞相、御史以謝天下乃可。", literal: "\" Ang said: \"Only by executing the Chancellor and the Censor to apologize to all under Heaven can it be done.", idiomatic: "\" Ang said, \"Only by executing the Chancellor and the Censor to apologize to all under Heaven can it be done.\"" },
  { zh: "」上即令丞相、御史逮考諸縣傳送淮南王不發封饋侍者，皆棄市；", literal: "\" The Emperor immediately ordered the Chancellor and Censor to arrest and try all along the relay who transported the king of Huainan without breaking the seal or supplying attendants—all were exposed in the market;", idiomatic: "\" The Emperor immediately ordered the Chancellor and Censor to arrest and try all along the relay who transported the king of Huainan without breaking the seal or supplying attendants—all were exposed in the market;" },
  { zh: "以列侯葬淮南王於雍，置守塚三十戶。", literal: "the king of Huainan was buried at Yong with the rites of a full marquis, and thirty households were set to guard the tomb.", idiomatic: "the king of Huainan was buried at Yong with the rites of a full marquis, and thirty households were set to guard the tomb." },
  { zh: "----3匈奴單于遣漢書曰：「前時，皇帝言和親事，稱書意，合歡。", literal: "----3 The Chanyu of the Xiongnu sent a letter to Han, saying: \"Previously the Emperor spoke of the marriage-alliance affair; the letter's intent was praised and accorded with joy.", idiomatic: "----3 The Chanyu of the Xiongnu sent a letter to Han, saying, \"Previously the Emperor spoke of the marriage-alliance affair; the letter's intent was praised and accorded with joy." },
  { zh: "漢邊吏侵侮右賢王；", literal: "Han frontier officials insulted and humiliated the Right Worthy King;", idiomatic: "Han frontier officials insulted and humiliated the Right Worthy King;" },
  { zh: "右賢王不請，聽後義盧侯難支等計，與漢吏相距。", literal: "the Right Worthy King did not request permission but heeded the plan of the Rear Yilu Marquis Nazhi and others and opposed Han officials.", idiomatic: "the Right Worthy King did not request permission but heeded the plan of the Rear Yilu Marquis Nazhi and others and opposed Han officials." },
  { zh: "絕二主之約，離兄弟之親，故罰右賢王，使之西求月氏擊之。", literal: "He broke the covenant of the two rulers and severed the kinship of brothers; therefore he punished the Wise King of the Right and sent him west to seek the Yuezhi and strike them.", idiomatic: "He broke the covenant of the two rulers and severed the bond of brotherhood; therefore he punished the Wise King of the Right and sent him west to seek the Yuezhi and attack them." },
  { zh: "以天之福，吏卒良，馬力強，以夷滅月氏，盡斬殺、降下，定之；", literal: "By Heaven's blessing, officers and soldiers were good and horses' strength strong; he extinguished the Yuezhi as barbarians, beheaded and killed all, made them submit, and settled them;", idiomatic: "By Heaven's blessing, officers and soldiers were capable and horses strong; he destroyed the Yuezhi as barbarians, beheaded and killed them all, made them submit, and settled them;" },
  { zh: "樓蘭、烏孫、呼揭及其旁二十六國，皆已為匈奴，諸引弓之民並為一家，北州以定。", literal: "Kroraina, Wusun, Hujie, and the twenty-six states beside them all already belonged to the Xiongnu; all bow-drawing peoples became one house, and the northern regions were settled.", idiomatic: "Kroraina, Wusun, Hujie, and the twenty-six states beside them all already belonged to the Xiongnu; all bow-drawing peoples became one house, and the northern regions were settled." },
  { zh: "願寢兵，休士卒，養馬，除前事，復故約，以安邊民。", literal: "I wish to lay down arms, rest officers and soldiers, nurture horses, set aside past affairs, restore the former covenant, and thereby settle the border people.", idiomatic: "I wish to lay down arms, rest the troops, nurture horses, set aside past affairs, restore the former covenant, and thereby settle the border people." },
  { zh: "皇帝即不欲匈奴近塞，則且詔吏民遠舍。", literal: "If the Emperor does not wish the Xiongnu near the passes, then for the time being let him decree that officials and people move their dwellings far off.", idiomatic: "If the Emperor does not wish the Xiongnu near the passes, then for the time being let him decree that officials and people move their dwellings far off." },
  { zh: "」帝報書曰：「單于欲除前事，復故約，朕甚嘉之。", literal: "\" The Emperor replied in a letter, saying: \"The Chanyu wishes to set aside past affairs and restore the former covenant—I greatly commend this.", idiomatic: "\" The Emperor replied in a letter: \"The Chanyu wishes to set aside past affairs and restore the former covenant—I greatly commend this." },
  { zh: "此古聖王之志也。", literal: "This is the aim of the ancient sage kings.", idiomatic: "This is the aim of the ancient sage kings." },
  { zh: "漢與匈奴約為兄弟，所以遺單于甚厚；", literal: "Han and the Xiongnu covenanted as brothers; for this reason what was sent to the Chanyu was very generous;", idiomatic: "Han and the Xiongnu covenanted as brothers; for this reason what was sent to the Chanyu was very generous;" },
  { zh: "倍約、離兄弟之親者，常在匈奴。", literal: "those who doubled the covenant and severed the kinship of brothers were constantly on the Xiongnu side.", idiomatic: "those who broke the covenant and severed the bond of brotherhood were constantly on the Xiongnu side." },
  { zh: "然右賢王事已在赦前，單于勿深誅！", literal: "Yet the Wise King of the Right's affair was already before the amnesty—the Chanyu must not punish him deeply!", idiomatic: "Yet the Wise King of the Right's affair was already before the amnesty—the Chanyu must not punish him severely!" },
  { zh: "單于若稱書意，明告諸吏，使無負約，有信，敬如單于書。", literal: "If the Chanyu accords with the letter's intent, let him clearly tell all his officers to not betray the covenant, to have good faith—[we] will respect it as the Chanyu's letter.", idiomatic: "If the Chanyu accords with the letter's intent, let him clearly tell all his officers not to betray the covenant and to keep faith—we will respect it as the Chanyu's letter." },
  { zh: "後頃之，冒頓死，子稽粥立，號曰老上單于。", literal: "After a short while Modun died; his son Jizhou was established, styled Laoshang Chanyu.", idiomatic: "After a short while Modun died; his son Jizhou was established, styled Laoshang Chanyu." },
  { zh: "老上單于初立，帝復遣宗室女翁主為單于閼氏，使宦者燕人中行說傅翁主。", literal: "When Laoshang Chanyu had just been established, the Emperor again sent a clanswoman, the Lady Wengzhu, to be the Chanyu's consort, and appointed the eunuch Yan man Zhonghang Yue to tutor the Lady Wengzhu.", idiomatic: "When Laoshang Chanyu had just been established, the Emperor again sent a clanswoman, the Lady Wengzhu, to be the Chanyu's consort, and appointed the eunuch Yan man Zhonghang Yue to tutor the Lady Wengzhu." },
  { zh: "說不欲行，漢強使之。", literal: "Yue did not wish to go; Han forced him to go.", idiomatic: "Yue did not wish to go; Han forced him to go." },
  { zh: "說曰：「必我也，為漢患者！", literal: "Yue said: \"It must be I who will bring harm upon Han!", idiomatic: "Yue said: \"It must be I who will bring harm upon Han!\"" },
  { zh: "」中行說既至，因降單于，單于甚親幸之。", literal: "\" When Zhonghang Yue had arrived, he thereupon defected to the Chanyu; the Chanyu was very intimate and favored toward him.", idiomatic: "\" When Zhonghang Yue had arrived, he thereupon defected to the Chanyu; the Chanyu was very intimate with him and greatly favored him." },
  { zh: "初，匈奴好漢繒絮、食物。", literal: "At first the Xiongnu loved Han silk floss and foodstuffs.", idiomatic: "At first the Xiongnu loved Han silk floss and foodstuffs." },
  { zh: "中行說曰：「匈奴人眾不能當漢之一郡，然所以強者，以衣食異，無仰於漢也。", literal: "Zhonghang Yue said: \"The Xiongnu in population cannot match a single Han commandery, yet the reason they are strong is that clothing and food differ and they have no dependence on Han.", idiomatic: "Zhonghang Yue said: \"The Xiongnu in population cannot match a single Han commandery, yet the reason they are strong is that clothing and food differ and they have no dependence on Han." },
  { zh: "今單于變俗，好漢物；", literal: "Now the Chanyu changes custom and loves Han goods;", idiomatic: "Now the Chanyu changes custom and loves Han goods;" },
  { zh: "漢物不過什二，則匈奴盡歸於漢矣。", literal: "if Han goods do not exceed two-tenths, then the Xiongnu will all belong to Han.", idiomatic: "if Han goods do not exceed two-tenths, then the Xiongnu will all belong to Han." },
  { zh: "」其得漢繒絮，以馳草棘中，衣胯皆裂敝，以示不如旃裘之完善也；", literal: "\" When they obtained Han silk floss, they galloped through grass and brambles with it; the clothing at the hips all split and wore out, to show it was not as complete as felt and fur robes;", idiomatic: "\" When they obtained Han silk floss, they galloped through grass and brambles with it; the clothing at the hips all split and wore out, to show it was not as durable as felt and fur robes;" },
  { zh: "得漢食物，皆去之，以示不如湩酪之便美也。", literal: "when they obtained Han foodstuffs, they all discarded them, to show they were not as convenient and fine as fermented mare's milk.", idiomatic: "when they obtained Han foodstuffs, they all discarded them, to show they were not as convenient and fine as fermented mare's milk." },
  { zh: "於是說教單于左右疏記，以計課其人眾、畜牧。", literal: "Thereupon Yue taught the Chanyu's attendants to keep written tallies and, by reckoning, assess their population and livestock.", idiomatic: "Thereupon Yue taught the Chanyu's attendants to keep written tallies and, by reckoning, assess their population and livestock." },
  { zh: "其遺漢書牘及印封，皆令長大，倨傲其辭，自稱「天地所生、日月所置匈奴大單于」。", literal: "When they sent letters and documents to Han and sealed them with the seal, he had them all made large, haughty in wording, styling himself \"Great Chanyu of the Xiongnu, begotten by Heaven and Earth, established by sun and moon.\"", idiomatic: "When they sent letters and documents to Han and sealed them with the seal, he had them all made large, haughty in wording, styling himself \"Great Chanyu of the Xiongnu, begotten by Heaven and Earth, established by sun and moon.\"" },
  { zh: "漢使或訾笑匈奴俗無禮義者，中行說輒窮漢使曰：「匈奴約束徑，易行；", literal: "When Han envoys sometimes reviled and laughed at Xiongnu custom for lacking ritual and righteousness, Zhonghang Yue would press the Han envoys hard, saying: \"Xiongnu regulations are direct and easy to carry out;", idiomatic: "When Han envoys sometimes reviled and laughed at Xiongnu custom for lacking ritual and righteousness, Zhonghang Yue would press the Han envoys hard: \"Xiongnu regulations are direct and easy to carry out;" },
  { zh: "君臣簡，可久；", literal: "lord and minister are simple and can long endure;", idiomatic: "lord and minister are simple and can long endure;" },
  { zh: "一國之政，猶一體也。", literal: "a state's government is like one body.", idiomatic: "a state's government is like one body." },
  { zh: "故匈奴雖亂，必立宗種。", literal: "Therefore though the Xiongnu are in disorder, they are sure to establish the lineage seed.", idiomatic: "Therefore though the Xiongnu are in disorder, they are sure to establish the lineage heir." },
  { zh: "今中國雖-{云}-有禮義，及親屬益疏則相殺奪，以至易姓，皆從此類也。", literal: "Now China, though it has -{云}- ritual and righteousness, when kin grow ever more distant they kill and seize from one another, even to the point of changing the surname—all from this sort of thing.", idiomatic: "Now China, though it has -{云}- ritual and righteousness, when kin grow ever more distant they kill and seize from one another, even to the point of changing the surname—all from this sort of thing." },
  { zh: "嗟！", literal: "Alas!", idiomatic: "Alas!" },
  { zh: "土室之人，顧無多辭，喋喋占占！", literal: "Men of earthen chambers—why so much talk, chattering and prognosticating!", idiomatic: "Men of earthen chambers—why so much talk, chattering and prognosticating!" },
  { zh: "顧漢所輸匈奴繒絮、米薛，令其量中，必善美而已矣，何以言為乎！", literal: "Simply see that what Han sends the Xiongnu in silk floss and grain is measured full and must be good and fine—that is enough; what need is there for words!", idiomatic: "Simply see that what Han sends the Xiongnu in silk floss and grain is measured full and must be good and fine—that is enough; what need is there for words!" },
  { zh: "且所給，備、善，則已；", literal: "Moreover, what is given—if complete and good, then that is enough;", idiomatic: "Moreover, what is given—if complete and good, then that is enough;" },
  { zh: "不備、苦惡，則候秋熟，以騎馳蹂而稼穡耳！", literal: "if not complete and bitterly bad, then wait until the autumn ripening and with cavalry gallop and trample the crops!", idiomatic: "if not complete and bitterly bad, then wait until the autumn ripening and with cavalry gallop and trample the crops!" },
  { zh: "」----4梁太傅賈誼上疏曰：", literal: "\" ----4 Grand Tutor of Liang Jia Yi submitted a memorial, saying:", idiomatic: "\" ----4 Grand Tutor of Liang Jia Yi submitted a memorial, saying:" },
  { zh: ":「臣竊惟今之事勢，可為痛哭者一，可為流涕者二，可為長太息者六；", literal: ":\"Your servant privately considers the present situation: there is one matter for which one may weep bitterly, two for which one may shed tears, and six for which one may sigh long;", idiomatic: ":\"Your servant privately considers the present situation: there is one matter for which one may weep bitterly, two for which one may shed tears, and six for which one may sigh long;" },
  { zh: "若其它背理而傷道者，難遍以疏舉。", literal: "as for other matters contrary to principle and injurious to the Way, it is hard to enumerate them all in a memorial.", idiomatic: "as for other matters contrary to principle and injurious to the Way, it is hard to enumerate them all in a memorial." },
  { zh: "進言者皆曰：『天下已安已治矣，』臣獨以為未也。", literal: "Those who advance counsel all say: 'All under Heaven is already secure and already well governed,' but your servant alone considers that it is not yet so.", idiomatic: "Those who advance counsel all say: 'The realm is already secure and already well governed,' but your servant alone considers that it is not yet so." },
  { zh: "曰安且治者，非愚則諛，皆非事實知治亂之體者也。", literal: "Those who say it is secure and well governed are either foolish or flatterers; none truly know the substance of order and disorder.", idiomatic: "Those who say it is secure and well governed are either foolish or flatterers; none truly know the substance of order and disorder." },
  { zh: "夫抱火厝之積薪之下而寢其上，火未及然，因謂之安；", literal: "To hold fire and place it under a pile of kindling yet sleep atop it—before the fire has reached the point of blazing, one therefore calls it secure;", idiomatic: "To hold fire and place it under a pile of kindling yet sleep atop it—before the fire has reached the point of blazing, one therefore calls it secure;" },
  { zh: "方今之勢，何以異此！", literal: "the present situation—how does it differ from this!", idiomatic: "the present situation—how does it differ from this!" },
  { zh: "陛下何不壹令臣得孰數之於前，因陳治安之策，試詳擇焉！", literal: "Why does Your Majesty not at once let your servant enumerate them in detail before you and, thereby presenting policies for securing order, try to choose carefully among them!", idiomatic: "Why does Your Majesty not at once let your servant enumerate them in detail before you and, thereby presenting policies for securing order, try to choose carefully among them!" },
  { zh: ":使為治，勞智慮，苦身體，乏鐘、鼓之樂，勿為可也。", literal: ":To govern may weary the mind's deliberation and distress the body, and lack the pleasure of bells and drums—that may be done.", idiomatic: ":To govern may weary the mind's deliberation and distress the body, and lack the pleasure of bells and drums—that may be done." },
  { zh: "樂與今同，而加之諸侯軌道，兵革不動，匈奴賓服，百姓素樸，生為明帝，沒為明神，名譽之美垂於無窮，使顧成之廟稱為太宗，上配太祖，與漢亡極，立經陳紀，為萬世法。", literal: "If pleasure is the same as today, yet in addition the feudal lords keep to the track, arms and armor are not moved, the Xiongnu guest and submit, the hundred surnames are plain and simple, living as a Brilliant Emperor and dying as a Brilliant Spirit, the beauty of fame extending without end, causing the temple of Gu Cheng to be styled Taizong, matching above with Taizu, with Han without end, establishing classics and setting forth ordinances as law for ten thousand generations.", idiomatic: "If pleasure is the same as today, yet in addition the feudal lords keep to the track, arms and armor are not moved, the Xiongnu guest and submit, the common people are plain and simple, living as a Brilliant Emperor and dying as a Brilliant Spirit, the beauty of fame extending without end, causing the temple of Gu Cheng to be styled Taizong, matching above with Taizu, with Han without end, establishing classics and setting forth ordinances as law for ten thousand generations." },
  { zh: "雖有愚幼、不肖之嗣，猶得蒙業而安。", literal: "Even if there were a foolish young or unworthy heir, he would still obtain the inherited enterprise and be secure.", idiomatic: "Even if there were a foolish young or unworthy heir, he would still obtain the inherited enterprise and be secure." },
  { zh: "以陛下之明達，因使少知治體者得佐下風，致此非難也。", literal: "With Your Majesty's brilliance and penetration, thereby letting those who slightly know the substance of governance assist below your wind—to achieve this is not difficult.", idiomatic: "With Your Majesty's brilliance and penetration, thereby letting those who slightly know the substance of governance assist below your wind—to achieve this is not difficult." },
  { zh: ":夫樹國固必相疑之勢，下數被其殃，上數爽其憂，甚非所以安上而全下也。", literal: ":To plant states is inherently a situation of mutual suspicion; those below repeatedly suffer their calamities, those above repeatedly miss their worries—this is very far from securing the superior and preserving the inferior.", idiomatic: ":To plant states is inherently a situation of mutual suspicion; those below repeatedly suffer their calamities, those above repeatedly miss their worries—this is very far from securing the superior and preserving the inferior." },
  { zh: "今或親弟謀為東帝，親兄之子西鄉而擊，今吳又見告矣。", literal: "Now perhaps a full younger brother plots to be Eastern Emperor, a full elder brother's son turns west and attacks, and now Wu has again been reported.", idiomatic: "Now perhaps a full younger brother plots to be Eastern Emperor, a full elder brother's son turns west and attacks, and now Wu has again been reported." },
  { zh: "天子春秋鼎盛，行義未過，德澤有加焉，猶尚如是；", literal: "The Son of Heaven is in the prime of life, his conduct and righteousness not yet in error, his virtue and grace still increasing—yet it is still like this;", idiomatic: "The Son of Heaven is in the prime of life, his conduct and righteousness not yet in error, his virtue and grace still increasing—yet it is still like this;" },
  { zh: "況莫大諸侯，權力且十此者虖！", literal: "how much more when great feudal lords have power nearly ten times this!", idiomatic: "how much more when great feudal lords have power nearly ten times this!" },
  { zh: ":然而天下少安，何也？", literal: ":Yet all under Heaven is slightly secure—why?", idiomatic: ":Yet the realm is slightly secure—why?" },
  { zh: "大國之王幼弱未壯，漢之所置傅、相方握其事。", literal: "The kings of great states are young and weak, not yet grown; the tutors and chancellors Han has appointed just now hold their affairs.", idiomatic: "The kings of great states are young and weak, not yet grown; the tutors and chancellors Han has appointed just now hold their affairs." },
  { zh: "數年之後，諸侯之王大抵皆冠，血氣方剛；", literal: "After several years, the kings of the feudal lords will for the most part all come of age, blood and vigor just firm;", idiomatic: "After several years, the kings of the feudal lords will for the most part all come of age, blood and vigor just firm;" },
  { zh: "漢之傅、相稱病而賜罷，彼自丞、尉以上遍置私人。", literal: "Han's tutors and chancellors will plead illness and be dismissed with gifts; they themselves from chancellors and commandants upward will everywhere place their own men.", idiomatic: "Han's tutors and chancellors will plead illness and be dismissed with gifts; they themselves from chancellors and commandants upward will everywhere place their own men." },
  { zh: "如此，有異淮南、濟北之為邪？", literal: "Like this, is there any difference from what Huainan and Jibei did?", idiomatic: "Like this, is there any difference from what Huainan and Jibei did?" },
  { zh: "此時而欲為治安，雖堯、舜不治。", literal: "At this time to wish to secure order—even Yao and Shun could not govern it.", idiomatic: "At this time to wish to secure order—even Yao and Shun could not govern it." },
  { zh: ":黃帝曰：『日中必熭，操刀必割！", literal: ":The Yellow Emperor said: 'At midday one must singe; holding a knife one must cut!", idiomatic: ":The Yellow Emperor said: 'At midday one must singe; holding a knife one must cut!" },
  { zh: "』今令此道順而全安甚易，不肯蚤為，已乃墮骨肉之屬而抗剄之，豈有異秦之季世虖！", literal: "' Now to make this course accordant and wholly secure is very easy; unwilling to act early, only afterward to cast down kin of flesh and bone and resist them with the executioner's blade—is this not the same as the late age of Qin!", idiomatic: "' Now to make this course accordant and wholly secure is very easy; unwilling to act early, only afterward to cast down kin of flesh and bone and resist them with the executioner's blade—is this not the same as the late age of Qin!" },
  { zh: "其異姓負強而動者，漢已幸而勝之矣，又不易其所以然；", literal: "Those of different surnames who relied on strength and moved—Han has already fortunately overcome them, yet does not change the reason it was so;", idiomatic: "Those of different surnames who relied on strength and moved—Han has already fortunately overcome them, yet does not change the reason it was so;" },
  { zh: "同姓襲是跡而動，既有征矣，其勢盡又復然。", literal: "those of the same surname follow these tracks and move—there are already signs; when their power is exhausted it will again be so.", idiomatic: "those of the same surname follow these tracks and move—there are already signs; when their power is exhausted it will again be so." },
  { zh: "殃禍之變，未知所移，明帝處之尚不能以安，後世將如之何！", literal: "The shift of calamity and disaster is unknown where it will move; a Brilliant Emperor facing it still cannot thereby be secure—how will later generations do!", idiomatic: "The shift of calamity and disaster is unknown where it will move; a Brilliant Emperor facing it still cannot thereby be secure—how will later generations do!" },
  { zh: ":臣竊跡前事，大抵強者先反。", literal: ":Your servant privately traces former affairs: for the most part the strong rebel first.", idiomatic: ":Your servant privately traces former affairs: for the most part the strong rebel first." },
  { zh: "長沙乃二萬五千戶耳，功少而最完，勢疏而最忠，非獨性異人也，亦形勢然也。", literal: "Changsha was only twenty-five thousand households; least in merit yet most complete, most distant in position yet most loyal—not solely because the nature was a different man, but also because the situation was so.", idiomatic: "Changsha was only twenty-five thousand households; least in merit yet most complete, most distant in position yet most loyal—not solely because the nature was a different man, but also because the situation was so." },
  { zh: "曩令樊、酈、絳、灌據數十城而王，今雖以殘亡可也；", literal: "If formerly Fan, Li, Jiang, and Guan had held dozens of cities and been kings, now even if reduced and destroyed that would be permissible;", idiomatic: "If formerly Fan, Li, Jiang, and Guan had held dozens of cities and been kings, now even if reduced and destroyed that would be permissible;" },
  { zh: "令信、越之倫列為徹侯而居，雖至今存可也。", literal: "if Xin, Yue, and their sort were ranked as marquises and dwelt thus, even to the present to remain would be permissible.", idiomatic: "if Xin, Yue, and their sort were ranked as marquises and dwelt thus, even to the present to remain would be permissible." },
  { zh: "然則天下之大計可知已：欲諸王之皆忠附，則莫若令如長沙王；", literal: "Then the great plan for all under Heaven can be known: if one wishes all the kings to be loyal and attached, there is nothing like making them like the King of Changsha;", idiomatic: "Then the great plan for the realm can be known: if one wishes all the kings to be loyal and attached, there is nothing like making them like the King of Changsha;" },
  { zh: "欲臣子勿菹醢，則莫若令如樊、酈等；", literal: "if one wishes ministers and sons not to be minced and salted, there is nothing like making them like Fan, Li, and the rest;", idiomatic: "if one wishes ministers and sons not to be minced and salted, there is nothing like making them like Fan, Li, and the rest;" },
  { zh: "欲天下之治安，莫若眾建諸侯而少其力。", literal: "if one wishes security and order for all under Heaven, there is nothing like establishing many feudal lords and diminishing their power.", idiomatic: "if one wishes security and order for the realm, there is nothing like establishing many feudal lords and diminishing their power." },
  { zh: "力少則易使以義，國小則亡邪心。", literal: "When power is little, they are easily employed by righteousness; when the state is small, perverse hearts perish.", idiomatic: "When power is little, they are easily employed by righteousness; when the state is small, perverse hearts perish." },
  { zh: "令海內之勢，如身之使臂，臂之使指，莫不制從，諸侯之君不敢有異心，輻湊並進而歸命天子。", literal: "Make the situation within the seas like the body employing the arm, the arm employing the finger—none not controlled and obedient; the lords of the feudal states dare not have divergent hearts, but like wheel spokes converging advance together and return their mandate to the Son of Heaven.", idiomatic: "Make the situation within the seas like the body employing the arm, the arm employing the finger—none not controlled and obedient; the lords of the feudal states dare not have divergent hearts, but like wheel spokes converging advance together and return their mandate to the Son of Heaven." },
  { zh: "割地定製，令齊、趙、楚各為若干國，使悼惠王、幽王、元王之子孫畢以次各受祖之分地，地盡而止；", literal: "Cut territory and fix institutions; let Qi, Zhao, and Chu each become several states; cause the descendants of King Daohui, King You, and King Yuan each in turn to receive their ancestor's allotted territory, stopping when the land is exhausted;", idiomatic: "Cut territory and fix institutions; let Qi, Zhao, and Chu each become several states; cause the descendants of King Daohui, King You, and King Yuan each in turn to receive their ancestor's allotted territory, stopping when the land is exhausted;" },
  { zh: "其分地眾而子孫少者，建以為國，空而置之，須其子孫生者舉使君之；", literal: "where allotted territory is much yet descendants few, establish it as a state, leave it empty and set it aside, and when descendants are born raise one to lord it;", idiomatic: "where allotted territory is much yet descendants few, establish it as a state, leave it empty and set it aside, and when descendants are born raise one to lord it;" },
  { zh: "一寸之地，一人之眾，天子亡所利焉，誠以定治而已。", literal: "an inch of land, a single man's multitude—the Son of Heaven has no profit from it; truly it is only to fix governance.", idiomatic: "an inch of land, a single man's multitude—the Son of Heaven has no profit from it; truly it is only to fix governance." },
  { zh: "如此，則臥赤子天下之上而安，植遺腹，朝委裘而天下不亂；", literal: "Like this, then lying an infant red atop all under Heaven one is secure, planting a posthumous heir, governing in court with a fur robe draped, yet all under Heaven is not in disorder;", idiomatic: "Like this, then lying an infant red atop the realm one is secure, planting a posthumous heir, governing in court with a fur robe draped, yet the realm is not in disorder;" },
  { zh: "當時大治，後世誦聖。", literal: "the age then greatly ordered, later generations chanting the sage.", idiomatic: "the age then greatly ordered, later generations chanting the sage." },
  { zh: "陛下誰憚而久不為此！", literal: "Your Majesty—whom do you fear that you long do not do this!", idiomatic: "Your Majesty—whom do you fear that you long do not do this!" },
  { zh: ":天下之勢方病大瘇，一脛之大幾如要，一指之大幾如股，平居不可屈伸，一二指慉，身慮亡聊。", literal: ":The situation of all under Heaven is just now afflicted with a great tumor: one shin nearly as large as the waist, one finger nearly as large as the thigh; in ordinary living one cannot bend or stretch; if one or two fingers are distressed, the body fears it has nothing to rely on.", idiomatic: ":The situation of the realm is just now afflicted with a great tumor: one shin nearly as large as the waist, one finger nearly as large as the thigh; in ordinary living one cannot bend or stretch; if one or two fingers are distressed, the body fears it has nothing to rely on." },
  { zh: "失今不治，必為錮疾，後雖有扁鵲，不能為已。", literal: "If one misses treating it now, it will surely become an incurable malady; afterward, though there were a Bian Que, he could not cure it.", idiomatic: "If one misses treating it now, it will surely become an incurable malady; afterward, though there were a Bian Que, he could not cure it." },
  { zh: "病非徒腫也。", literal: "The disease is not only swelling.", idiomatic: "The disease is not only swelling." },
  { zh: "又苦蹠盭。", literal: "There is also the distress of foot ailments.", idiomatic: "There is also the distress of foot ailments." },
  { zh: "元王之子，帝之從弟也；", literal: "The son of King Yuan was the Emperor's younger cousin;", idiomatic: "The son of King Yuan was the Emperor's younger cousin;" },
  { zh: "今之王者，從弟之子也。", literal: "the present king is the son of a younger cousin.", idiomatic: "the present king is the son of a younger cousin." },
  { zh: "惠王之子，親兄子也，今之王者，兄子之子也。", literal: "The son of King Hui was a full elder brother's son; the present king is a brother's son's son.", idiomatic: "The son of King Hui was a full elder brother's son; the present king is a brother's son's son." },
  { zh: "親者或亡分地以安天下，疏者或制大權以逼天子，臣故曰非徒病腫也，又苦蹠炙盭。", literal: "Among the close, some lack allotted territory yet secure all under Heaven; among the distant, some wield great power to press the Son of Heaven—your servant therefore says it is not only the disease of swelling but also the distress of roasted foot ailments.", idiomatic: "Among the close, some lack allotted territory yet secure the realm; among the distant, some wield great power to press the Son of Heaven—your servant therefore says it is not only the disease of swelling but also the distress of roasted foot ailments." },
  { zh: "可痛哭者，此病是也。", literal: "That for which one may weep bitterly—this disease is it.", idiomatic: "That for which one may weep bitterly—this disease is it." },
  { zh: ":天下之勢方倒懸。", literal: ":The situation of all under Heaven is just now inverted and hung.", idiomatic: ":The situation of the realm is just now inverted and hung." },
  { zh: "凡天子者，天下之首。", literal: "In general the Son of Heaven is the head of all under Heaven.", idiomatic: "In general the Son of Heaven is the head of all under Heaven." },
  { zh: "何也？", literal: "Why?", idiomatic: "Why?" },
  { zh: "上也。", literal: "Because he is above.", idiomatic: "Because he is above." },
  { zh: "蠻夷者，天下之足。", literal: "The barbarians are the feet of all under Heaven.", idiomatic: "The barbarians are the feet of all under Heaven." },
  { zh: "何也？", literal: "Why?", idiomatic: "Why?" },
  { zh: "下也。", literal: "Because they are below.", idiomatic: "Because they are below." },
  { zh: "今匈奴嫚侮侵掠，至不敬也；", literal: "Now the Xiongnu insult, encroach, and plunder, reaching to lack of respect;", idiomatic: "Now the Xiongnu insult, encroach, and plunder, reaching to lack of respect;" },
  { zh: "而漢歲致金絮采繒以奉之。", literal: "yet Han year after year sends gold, floss, colored silks, and brocades to serve them.", idiomatic: "yet Han year after year sends gold, floss, colored silks, and brocades to serve them." },
  { zh: "足反居上，首顧居下，倒縣如此，莫之能解，猶為國有人乎？", literal: "The feet instead dwell above, the head instead dwells below—inverted and hung like this, none able to resolve it; is there still someone in the state?", idiomatic: "The feet instead dwell above, the head instead dwells below—inverted and hung like this, none able to resolve it; is there still someone in the state?" },
  { zh: "可為流涕者此也。", literal: "That for which one may shed tears is this.", idiomatic: "That for which one may shed tears is this." },
  { zh: ":今不獵猛敵而獵田彘，不搏反寇而搏畜菟，翫玩細娛而不圖大患，德可遠加而直數百里外，威令不伸，可為流涕者此也。", literal: ":Now one does not hunt fierce enemies but hunts field pigs; does not grapple with rebellious bandits but grapples with domestic rabbits; indulges in petty amusements and does not plan for great peril; virtue could extend far yet reaches only several hundred li beyond, authority and orders not extended—that for which one may shed tears is this.", idiomatic: ":Now one does not hunt fierce enemies but hunts field pigs; does not grapple with rebellious bandits but grapples with domestic rabbits; indulges in petty amusements and does not plan for great peril; virtue could extend far yet reaches only several hundred li beyond, authority and orders not extended—that for which one may shed tears is this." },
  { zh: ":今庶人屋壁得為帝服，倡優下賤得為-{后}-飾；", literal: ":Now commoners' house walls may have imperial dress; actors and lowly performers may have -{后}- adornments;", idiomatic: ":Now commoners' house walls may have imperial dress; actors and lowly performers may have -{后}- adornments;" },
  { zh: "且帝之身自衣皁綈，而富民牆屋被文繡；", literal: "moreover the Emperor's own person wears black coarse silk, while rich men's wall houses are draped with patterned embroidery;", idiomatic: "moreover the Emperor's own person wears black coarse silk, while rich men's wall houses are draped with patterned embroidery;" },
  { zh: "天子之-{后}-以緣其領，庶人孽妾以緣其履；", literal: "the Son of Heaven's -{后}- uses trim for her collar, while a commoner's concubine uses trim for her shoes;", idiomatic: "the Son of Heaven's -{后}- uses trim for her collar, while a commoner's concubine uses trim for her shoes;" },
  { zh: "此臣所謂舛也。", literal: "This is what your servant calls perversity.", idiomatic: "That is the inversion I mean." },
  { zh: "夫百人作之不能衣一人，欲天下亡寒，胡可得也；", literal: "Now a hundred men make it yet cannot clothe one man—if one desires all under Heaven to have no cold, how can it be obtained?", idiomatic: "A hundred laborers may weave enough to dress one wastrel—how then can you hope that no one in the realm will shiver?" },
  { zh: "一人耕之，十人聚而食之，欲天下亡饑，不可得也；", literal: "One man plows it, ten men gather and eat it—if one desires all under Heaven to have no hunger, it cannot be obtained.", idiomatic: "One farmer tills while ten mouths feast on his harvest—you will never banish famine that way." },
  { zh: "饑寒切於民之肌膚，欲其亡為奸邪，不可得也。", literal: "Hunger and cold cut into the people's skin and flesh—if one desires that they not commit wickedness and deviance, it cannot be obtained.", idiomatic: "When hunger and cold bite into the flesh, you cannot expect ordinary folk to stay honest." },
  { zh: "可為長太息者此也。", literal: "What may be long sighed for is this.", idiomatic: "This is another of the six causes for a long, bitter sigh." },
  { zh: ":商君遺禮義，棄仁恩，並心於進取；", literal: ": Lord Shang cast aside ritual and righteousness, abandoned benevolence and kindness, united hearts on advance and seizure;", idiomatic: ": When Lord Shang discarded ritual, benevolence, and every humane restraint in favor of naked ambition," },
  { zh: "行之二歲，秦俗日敗。", literal: "practiced two years, and Qin's customs daily decayed.", idiomatic: "within two years the customs of Qin rotted away." },
  { zh: "故秦人家富子壯則出分，家貧子壯則出贅；", literal: "Therefore in Qin, if the family was rich and the son grown, then he went out to divide; if the family was poor and the son grown, then he went out to be a son-in-law.", idiomatic: "Hence in Qin a rich family drove out grown sons to split the estate, while a poor family sent them out as indentured sons-in-law;" },
  { zh: "借父櫌鉏，慮有德色；", literal: "Borrowing from the father a hoe, one fears there will be a look of conferred virtue;", idiomatic: "a son who borrows his father's hoe expects a scowl of condescending favor in return;" },
  { zh: "母取箕帚，立而誶語；", literal: "The mother takes broom and dustpan—standing, they revile with words.", idiomatic: "a mother-in-law who lends her broom hears muttered curses before her feet have left the room;" },
  { zh: "抱哺其子，與公並居；", literal: "Holding and suckling her child, with the father-in-law she dwells together.", idiomatic: "a daughter-in-law nurses her baby while lounging as insolently as her father-in-law;" },
  { zh: "婦姑不相說，則反脣而相稽；", literal: "If wife and mother-in-law are not pleased with each other, they turn lips and mutually investigate.", idiomatic: "when wife and mother-in-law quarrel, they answer each other with sneers and spiteful jibes;" },
  { zh: "其慈子、耆利，不同禽獸者亡幾耳。", literal: "Their loving children and craving profit—not differing from birds and beasts is but little.", idiomatic: "parental tenderness there is, but it is love of gain; they stand barely a hair's breadth above the beasts." },
  { zh: "今其遺見餘俗，猶尚未改，棄禮誼，捐廉恥日甚，可謂月異而歲不同矣。", literal: "Now its leftover legacy and surviving customs have still not yet changed; casting aside ritual and righteousness, throwing away integrity and shame daily more extreme—it can be called month different and year not the same.", idiomatic: "The foul habits Qin left behind linger still: ritual and right are abandoned, honor is shed, and the decline worsens by the month until the year is unrecognizable." },
  { zh: "逐利不耳，慮非顧行也；", literal: "They pursue profit and nothing else; they do not consider or look to conduct.", idiomatic: "Profit is all they hear; decency never enters the reckoning;" },
  { zh: "今其甚者殺父兄矣。", literal: "Now in the extreme cases they kill fathers and elder brothers.", idiomatic: "until some go so far as to murder father or brother." },
  { zh: "而大臣特以簿書不報、期會之間以為大故，至於俗流失，世壞敗，因恬而不知怪，慮不動於耳目，以為是適然耳。", literal: "Yet great ministers take only that ledgers are not reported and between deadline meetings as the great matter; as for custom flowing away and the age ruined and defeated, they are calm thereby and do not know it strange; care is not moved in ear and eye—they think this is only fitting.", idiomatic: "Yet high ministers fuss only over late paperwork and missed deadlines, as if those were the gravest crises. When custom rots and society crumbles, they remain placid and call it normal, for nothing their eyes or ears report seems worth a second thought." },
  { zh: "夫移風易俗，使天下回心而鄉道，類非俗吏之所能為也。", literal: "Now to shift custom and change vulgar ways, causing all under Heaven to turn heart and incline to the Way—in kind is not what vulgar clerks can do.", idiomatic: "To shift the wind of custom and turn the empire's heart toward the Way is not work for petty bureaucrats." },
  { zh: "俗吏之所務，在於刀筆、筐篋而不知大體。", literal: "What vulgar clerks attend to lies in knife-brush and basket-box, and they do not know the great substance.", idiomatic: "Such men live for their brush cases and document satchels; they have no grasp of the larger pattern." },
  { zh: "陛下又不自憂，竊為陛下惜之！", literal: "Your Majesty again does not worry for yourself—your servant privately pities this for Your Majesty!", idiomatic: "When Your Majesty will not even trouble yourself over it, I can only grieve in private!" },
  { zh: "豈如今定經制，令君君、臣臣，上下有差，父子六親各得其宜。", literal: "How about now fixing the classics and system, ordering lord lord and minister minister, high and low having gradation, father and son and six kin each obtaining their fitness.", idiomatic: "Better to fix the fundamental laws now: true sovereignty above, true service below, clear ranks from top to bottom, every family relationship in its proper place." },
  { zh: "此業壹定，世世常安，而後有所持循矣；", literal: "Once this enterprise is fixed, age after age there is constant peace, and afterward there is something to hold and follow.", idiomatic: "Once that settlement is made, peace can pass down the generations, and posterity will have a model to follow;" },
  { zh: "若夫經制不定，是猶渡江河亡維楫，中流而遇風波，船必覆矣。", literal: "If the classics and system are not fixed, it is like crossing rivers and seas without ropes and oars—midstream meeting wind and waves, the boat must capsize.", idiomatic: "leave the basic order unsettled and you cross a great river without oar or rudder: meet a squall midstream and the vessel must founder." },
  { zh: "可為長太息者此也。", literal: "What may be long sighed for is this.", idiomatic: "This too is cause for one of the six long sighs." },
  { zh: ":夏、殷、周為天子皆數十世，秦為天子二世而亡。", literal: ": Xia, Yin, and Zhou as Sons of Heaven each for several tens of generations; Qin as Son of Heaven two generations and perished.", idiomatic: ": The Xia, Shang, and Zhou each held the mandate for dozens of reigns; Qin held it for two reigns and collapsed." },
  { zh: "人性不甚相遠也，何三代之君有道之長而秦無道之暴也？", literal: "Human nature is not greatly distant from itself—why did the lords of the Three Ages have the Way and long endure, while Qin lacked the Way and was violent?", idiomatic: "Human nature has not changed much across the ages—so why did the rulers of the three ancient dynasties enjoy long, virtuous reigns while Qin's lack of the Way brought sudden ruin?" },
  { zh: "其故可知也。", literal: "Its reason can be known.", idiomatic: "The reason is not hard to see." },
  { zh: "古之王者，太子乃生，固舉以禮，有司齊肅端冕，見之南郊，過闕則下，過廟則趨，故自為赤子，而教固已行矣。", literal: "The kings of antiquity: when the heir apparent was just born, solidly they raised him with ritual; officials fasting and solemn with straight caps and robes showed him at the southern suburb; passing a tower gate then dismounting, passing a temple then hurrying—therefore from being a red child, instruction was already practiced.", idiomatic: "The kings of old, as soon as the heir was born, received him with full ceremony: officers in fasting garb and formal regalia presented him at the southern suburb; he dismounted at the palace gate and quickened his step past the ancestral shrine—thus moral instruction began while he was still in swaddling clothes." },
  { zh: "孩提有識，三公、三少明孝仁禮義以道習之，逐去邪人，不使見惡行，於是皆選天下之端士、孝悌博聞有道術者以衛翼之，使與太子居處出入。", literal: "When the child in arms had awareness, the three dukes and three juniors enlightened him in filiality, benevolence, ritual, and righteousness to guide and drill him, drove away wicked men, did not allow him to see evil conduct; thereupon all selected the realm's upright gentlemen, filial and fraternal, broadly learned and possessed of the Way and arts, to guard and wing him, causing them to dwell, rise, and go out with the heir apparent.", idiomatic: "From the moment the boy could understand speech, the six mentors drilled him in filial piety, humanity, ritual, and right, drove away corrupt companions, and shielded him from base example; the court then chose the finest scholars in the land—men of filial piety, wide learning, and proven principle—to attend the heir at home and abroad." },
  { zh: "故太子乃生而見正事，聞正言，行正道，左右前後皆正人也。", literal: "Therefore the heir apparent from birth saw correct affairs, heard correct words, walked correct paths; to left and right, before and behind, all were correct men.", idiomatic: "Thus from birth the crown prince saw only upright conduct, heard only upright speech, and walked only upright paths; every face around him belonged to a good man." },
  { zh: "夫習與正人居之不能毋正，猶生長於齊不能不齊言也；", literal: "Now habit with correct men dwelling—one cannot but be correct, just as growing up in Qi one cannot but speak Qi speech;", idiomatic: "Live always among the upright and you cannot help becoming upright, just as a child raised in Qi cannot help speaking the Qi dialect;" },
  { zh: "習與不正人居之不能毋不正，猶生長於楚之地不能不楚言也。", literal: "habit with incorrect men dwelling—one cannot but be incorrect, just as growing up in Chu's land one cannot but speak Chu speech.", idiomatic: "dwell among the crooked and you will twist like them, as surely as a child of Chu speaks the Chu tongue." },
  { zh: "孔子曰：『少成若天性，習貫如自然。", literal: "Confucius said: \"What is formed in youth is like nature; habit drilled is like what is natural.", idiomatic: "Confucius said, \"What the boy learns in youth becomes second nature; habit hardens into instinct." },
  { zh: "』習與智長，故切而不愧；", literal: "\" Habit grows with wisdom, therefore cutting yet not ashamed;", idiomatic: "\" Counsel grows sharper as his mind matures, so rebukes can be blunt without giving offense;" },
  { zh: "化與心成，故中道若性。", literal: "transformation completes with the heart, therefore hitting the Way is like nature.", idiomatic: "moral transformation fuses with his inner heart until the middle path feels as natural as instinct." },
  { zh: "夫三代之所以長久者，以其輔翼太子有此具也。", literal: "Now why the Three Ages were long enduring lies in that their assisting and winging the heir apparent had these provisions.", idiomatic: "The three dynasties endured because they furnished the crown prince with exactly this support." },
  { zh: "及秦而不然，使趙高傅胡亥而教之獄，所習者非斬、劓人，則夷人之三族也。", literal: "When it came to Qin it was not so: they made Zhao Gao tutor Huhai and taught him in the prison; what he practiced was not beheading and nose-cutting men, then exterminating men's three clans.", idiomatic: "Qin did the opposite: Zhao Gao was made tutor to Huhai and schooled him in the jail, where he learned nothing but beheadings, mutilations, and the extermination of whole clans." },
  { zh: "胡亥今日即位而明日射人，忠諫者謂之誹謗，深計者謂之妖言，其視殺人若艾草菅然。", literal: "Huhai today ascended the throne and tomorrow shot men; loyal remonstrators were called slander, deep planners were called perverse speech—he regarded killing men as mugwort and rush grass.", idiomatic: "Huhai took the throne one day and the next was shooting people; loyal counsel was labeled slander, thoughtful policy was labeled sedition, and he treated killing men like mowing weeds." },
  { zh: "豈惟胡亥之性惡哉？", literal: "Was it only Huhai's nature that was wicked?", idiomatic: "Was Huhai's nature alone to blame?" },
  { zh: "彼其所以道之者非其理故也。", literal: "That by which they guided him was not its proper pattern—therefore.", idiomatic: "Those who guided him taught him what was not right." },
  { zh: "鄙諺曰：『前車覆，後車誡。", literal: "A rustic proverb says: \"The front cart overturns; the rear cart takes warning.", idiomatic: "A common proverb runs, \"When the lead wagon spills, the wagon behind should beware." },
  { zh: "』秦世之所以亟絕者，其轍跡可見也；", literal: "\" Why the Qin age was quickly cut off—the rut tracks can be seen;", idiomatic: "\" Why Qin fell so swiftly is written clear as wagon ruts in the mud;" },
  { zh: "然而不避，是後車又將覆也。", literal: "yet not avoiding them—this is the rear cart again about to overturn.", idiomatic: "yet we swerve aside from none of its mistakes—the second wagon is about to overturn." },
  { zh: "天下之命，縣於太子，太子之善，在於早諭教與選左右。", literal: "The fate of all under Heaven hangs on the heir apparent; the heir apparent's excellence lies in early instruction and selecting those to left and right.", idiomatic: "The fate of the empire hangs from the crown prince; his worth depends on early teaching and careful choice of companions." },
  { zh: "夫心未濫而先諭都，則化易成也；", literal: "Now if before the heart is dissolute one first instructs Du, then transformation is easy to complete;", idiomatic: "Instruct the heart before passions run wild and moral transformation comes easily;" },
  { zh: "開於道術智誼之指，則教之力也；", literal: "opening him to the aims of the Way, arts, wisdom, and righteousness—then is the power of teaching.", idiomatic: "open his mind to the Way, to method, to wisdom and right—that is the true force of education;" },
  { zh: "若其服習積貫，則左右而已。", literal: "If it is a matter of clothing habit and accumulated practice, then it is only those to left and right.", idiomatic: "if you want lasting habit and inward conviction, nothing matters more than those who stand at his elbow." },
  { zh: "夫胡、粵之人，生而同聲，嗜欲不異；", literal: "Now the men of Hu and Yue are born with the same cries; cravings and desires are not different;", idiomatic: "The Hu and the Yue are born with the same infant cry and the same appetites;" },
  { zh: "及其長而成俗，累數譯而不能相通，有雖死而不相為者，則教習然也。", literal: "when they have grown and customs form, piled translators cannot make them communicate; there are those who though dead do not act for each other—then it is teaching and habit that make it so.", idiomatic: "grown to manhood they grow so far apart that stacks of interpreters cannot bridge their speech, and men will die before aiding the other—all from upbringing and habit." },
  { zh: "臣故曰選左右、早諭教最急。", literal: "Therefore your servant says selecting those to left and right and early instruction are most urgent.", idiomatic: "I repeat: choose his companions and begin his instruction early—nothing is more urgent." },
  { zh: "夫教得而左右正，則太子正矣，太子正而天下定矣。", literal: "Now if teaching is obtained and those to left and right are correct, then the heir apparent is correct; the heir apparent is correct and all under Heaven is settled.", idiomatic: "When teaching succeeds and his attendants are upright, the heir becomes upright; when the heir is upright, the realm is settled." },
  { zh: "《書》曰：『一人有慶，兆民賴之。", literal: "The Documents says: \"When one man has blessing, the myriad people rely on him.", idiomatic: "The Documents says, \"When the ruler knows blessing, the myriad people lean upon him." },
  { zh: "』此時務也。", literal: "\" This is the pressing task of the times.", idiomatic: "\" That is the business of the hour." },
  { zh: ":凡人之智，能見已然，不能見將然。", literal: ": In general men's wisdom can see what is already so, cannot see what will be so.", idiomatic: ": Ordinary wit sees only what has already happened; it cannot see what is coming." },
  { zh: "夫禮者禁於將然之前，而法者禁於已然之後，是故法之所為用易見而禮之所為生難知也。", literal: "Now ritual forbids before what will be so; law forbids after what is already so; therefore what law applies is easy to see, while what ritual does in giving birth is hard to know.", idiomatic: "Ritual stops wrong before it sprouts; law punishes wrong after the fact. The effects of law are obvious; the quiet work of ritual is easy to overlook." },
  { zh: "若夫慶賞以勸善，刑罰以懲惡，先王執此之政，堅如金石；", literal: "As for rewards and grants to encourage good, punishments and fines to chastise evil—the former kings grasped this in government, firm as metal and stone;", idiomatic: "Rewards to encourage good and punishments to check evil—the ancient kings wielded both, unshakable as metal;" },
  { zh: "行此之令，信如四時；", literal: "carried out these orders, trustworthy as the four seasons;", idiomatic: "as reliable as the seasons;" },
  { zh: "據此之公，無私如天地，豈顧不用哉？", literal: "relied on this fairness, without private bias like Heaven and Earth—how could they have been unwilling to use them?", idiomatic: "as impartial as heaven and earth. Of course they used them—why would they not?" },
  { zh: "然而曰禮雲、禮雲者，貴絕惡於未萌而起教於微眇，使民日遷善、遠罪而不自知也。", literal: "Yet when it is said \"ritual, ritual,\" what is prized is cutting off evil before it sprouts, and raising instruction in what is subtle and minute, causing the people day by day to move toward good and far from crime without themselves knowing it.", idiomatic: "When we speak of ritual, we mean killing evil in the bud and teaching in the finest grain of life, so the people drift toward goodness and away from crime without noticing the tug." },
  { zh: "孔子曰：『聽訟，吾猶人也；", literal: "Confucius said: \"In hearing lawsuits, I am like other men;", idiomatic: "Confucius said, \"In hearing cases I am no wiser than other men;" },
  { zh: "必也使毋訟乎！", literal: "it must be to cause there to be no lawsuits!\"", idiomatic: "what I want is to bring it about that there are no cases at all!\"" },
  { zh: "』為人主計者，莫如先審取舍，取舍之極定於內而安危之萌應於外矣。", literal: "\" For one who plans for the lord of men, nothing is like first examining what to take and what to reject; when the utmost of taking and rejecting is fixed within, then the sprouts of security and peril respond without.", idiomatic: "\" For a ruler's counselor, nothing comes before weighing what to embrace and what to reject; once that choice is settled within, the seeds of safety or ruin appear without." },
  { zh: "秦王之欲尊宗廟而安子孫，與湯、武同。", literal: "The King of Qin's desire to honor the ancestral temple and secure sons and grandsons was the same as Tang's and Wu's.", idiomatic: "The Qin king wanted to glorify his shrines and secure his line no less than Tang or Wu." },
  { zh: "然而湯、武廣大其德行，六七百歲而弗失，秦王治天下十餘歲則大敗。", literal: "Yet Tang and Wu enlarged their virtue and conduct, six or seven hundred years and did not lose it; the King of Qin governed all under Heaven, and in over ten years there was great defeat.", idiomatic: "Yet Tang and Wu broadened their virtue and held the realm six or seven hundred years, while Qin's way collapsed in little more than a decade." },
  { zh: "此亡他故矣：湯、武之定取舍審而秦王之定取舍不審矣。", literal: "This has no other reason: Tang and Wu's fixing of taking and rejecting was careful, while the King of Qin's fixing of taking and rejecting was not careful.", idiomatic: "No other cause lies beneath it: Tang and Wu chose their course with care, while the King of Qin chose his with blind recklessness." },
  { zh: "夫天下，大器也；", literal: "Now all under Heaven is a great vessel.", idiomatic: "The empire is a great vessel;" },
  { zh: "今人之置器，置諸安處則安，置諸危處則危。", literal: "Now when men set a vessel, if they set it in a secure place it is secure; if they set it in a perilous place it is perilous.", idiomatic: "set a precious thing on a safe shelf and it stays whole; set it on a ledge over a cliff and it will shatter." },
  { zh: "天下之情，與器無以異，在天子之所置之。", literal: "The disposition of all under Heaven does not differ from a vessel—it lies in where the Son of Heaven sets it.", idiomatic: "The realm is no different: everything depends on where the Son of Heaven places it." },
  { zh: "湯、武置天下於仁、義、禮、樂，累子孫數十世，此天下所共聞也；", literal: "Tang and Wu set all under Heaven on benevolence, righteousness, ritual, and music, piling sons and grandsons for several tens of generations—this all under Heaven jointly has heard;", idiomatic: "Tang and Wu set the realm on benevolence, right, ritual, and music, and their houses ruled dozens of generations—that story the whole world knows by heart;" },
  { zh: "秦王置天下於法令、刑罰，禍幾及身，子孫誅絕，此天下之所共見也。", literal: "The King of Qin set all under Heaven on laws, orders, punishments, and fines; calamity nearly reached his person, sons and grandsons were executed to extinction—this all under Heaven jointly has seen.", idiomatic: "the Qin king set the realm on statutes and the rack: disaster brushed his own skin, and his line was cut off root and branch—that spectacle everyone has seen with his own eyes." },
  { zh: "是非其明效大驗邪！", literal: "Is this not its clear effect and great proof!", idiomatic: "Could proof be clearer or the lesson louder?" },
  { zh: "人之言曰：『聽言之道，必以其事觀之，則言者莫敢妄言。", literal: "Men's words say: \"In the way of listening to words, one must observe them by their affairs—then those who speak dare not speak wildly.", idiomatic: "Men say, \"Test every counsel against the facts, and no one will dare traffic in empty words." },
  { zh: "』今或言禮誼之不如法令，教化之不如刑罰，人主胡不引殷、周、秦事以觀之也！", literal: "\" Now some say ritual and righteousness are not as good as laws and orders, transformation and teaching not as good as punishments and fines—why does the lord of men not cite Yin, Zhou, and Qin affairs to observe it!", idiomatic: "\" If anyone claims ritual cannot match statute or moral suasion the rack, let the ruler weigh the histories of Yin, Zhou, and Qin and judge for himself!" },
  { zh: "人主之尊譬如堂，群臣如陛，眾庶如地。", literal: "The lord of men's honor is like a hall; the host of ministers like steps; the multitude like the ground.", idiomatic: "The ruler's majesty is the high hall; his ministers are the stair; the common people are the earth below." },
  { zh: "故陛九級上，廉遠地，則堂高；", literal: "Therefore when the steps are nine tiers up, the edge far from the ground, then the hall is high;", idiomatic: "Many tiers of steps lift the hall high above the ground;" },
  { zh: "陛無級，廉近地，則堂卑。", literal: "when the steps lack tiers, the edge near the ground, then the hall is low.", idiomatic: "strip away those steps and the hall sits almost in the dust." },
  { zh: "高者難攀，卑者易陵，理勢然也。", literal: "What is high is hard to climb; what is low is easy to overrun—pattern and posture are thus.", idiomatic: "What stands high is hard to storm; what lies low invites trampling—that is simply how things work." },
  { zh: "故古者聖王制為等列，內有公、卿、大夫、士，外有公、侯、伯、子、男，然後有官師、小吏，延及庶人，等級分明而天子加焉，故其尊不可及也。", literal: "Therefore in antiquity the sage kings made ranked arrays: within there were dukes, ministers, great officers, and knights; without there were dukes, marquises, earls, viscounts, and barons; afterward there were official masters and petty clerks, extending to the common people—grades and ranks were clear, and the Son of Heaven was added above them; therefore his honor could not be reached.", idiomatic: "The sage kings built a ladder of rank—within the court from dukes down to ordinary knights, without from feudal princes down to petty clerks and then the people—each step distinct, with the Son of Heaven alone above them all. That is how his majesty became unapproachable." },
  { zh: ":里諺曰：『欲投鼠而忌器。", literal: ": A hamlet proverb says: \"Desiring to throw at a rat yet fearing the vessel.", idiomatic: ": The proverb says, \"You hesitate to strike the rat for fear of the vase beside it." },
  { zh: "』此善諭也。", literal: "\" This is a good analogy.", idiomatic: "\" That is apt counsel." },
  { zh: "鼠近於器，尚憚不投，恐傷其器，況於貴臣之近主乎！", literal: "When the rat is near the vessel, still one fears not to throw, fearing to harm the vessel—how much more for noble ministers near the lord!", idiomatic: "Even a rat beside a precious jar gives pause—how much more a high minister standing at the ruler's elbow!" },
  { zh: "廉恥節禮以治君子，故有賜死而亡戮辱。", literal: "With integrity, shame, restraint, and ritual they governed gentlemen; therefore there was granted death but no shame of execution.", idiomatic: "Integrity, shame, and ritual governed the gentleman class: they might be sentenced to die, but never dragged through public mutilation." },
  { zh: "是以黥、劓之罪不及大夫，以其離主上不遠也。", literal: "Therefore branding and nose-cutting punishments did not reach great officers, because their distance from the lord above was not far.", idiomatic: "Branding and cropping never touched a grandee, for he stood too close to the throne." },
  { zh: "禮：不敢齒君之路馬，蹴其芻者有罰，所以為主上豫遠不敬也。", literal: "By ritual one did not dare rank the lord's road horses; one who kicked their fodder had punishment—this was why for the lord above beforehand to keep far lack of respect.", idiomatic: "Ritual forbade even naming the age of the ruler's team horses; kick their fodder and you were fined—all to keep contempt at a distance from the ruler." },
  { zh: "今自王、侯、三公之貴，皆天子之所改容而禮之也，古天子之所謂伯父、伯舅也；", literal: "Now from kings, marquises, and the three dukes' honor—all are those whom the Son of Heaven changes countenance and treats with ritual, what antiquity's Son of Heaven called uncle and elder uncle;", idiomatic: "Today kings, marquises, and the three dukes—men the emperor greets with altered mien, the very kin the ancients called uncle or great-uncle;" },
  { zh: "而令與眾庶同黥、劓、髡、刖、笞、傌、棄市之法，然則堂不無陛虖！", literal: "yet ordering them to share with the multitude branding, cropping, shaving, cutting off feet, flogging, exposure, and execution in the market—then is not the hall without its steps!", idiomatic: "are thrown to the same branding, cropping, shaving, hobbling, flogging, and public execution as common felons. Is that not tearing the steps from under the hall!" },
  { zh: "被戮辱者不泰迫虖！", literal: "Those who suffer execution and shame—are they not too pressed!", idiomatic: "Are not those who suffer such shame driven past endurance!" },
  { zh: "廉恥不行，大臣無乃握重權、大官而有徒隸無恥之心虖！", literal: "With integrity and shame not practiced, is it not that great ministers grasp heavy power, great offices yet have the heart of convicts and slaves without shame!", idiomatic: "When shame no longer restrains them, will not great officers who hold the levers of power begin to think like shackled slaves!" },
  { zh: "夫望夷之事，二世見當以重法者，投鼠而不忌器之習也。", literal: "Now as for the affair at Wangyi, when the Second Generation met judgment with heavy law—it was the habit of throwing at rats without fearing the vessel.", idiomatic: "The slaughter at Wangyi Palace, where the Second Emperor fell to harsh law, was the fruit of striking rats without regard for the vase." },
  { zh: "臣聞之：履雖鮮不加於枕，冠雖敝不以苴履。", literal: "Your servant has heard: though shoes be fresh, they are not placed on the pillow; though the cap be worn, it is not used to plug shoes.", idiomatic: "I have heard it said: never put new shoes on the pillow, nor plug worn-out shoes with your cap—each thing keeps its proper use." },
  { zh: "夫嘗已在貴寵之位，天子改容而禮貌之矣，吏民嘗俯伏以敬畏之矣；", literal: "Now for one who has already been in honored and favored rank, the Son of Heaven has changed countenance and treated him with ritual courtesy; clerks and people have bent low in awe and reverence;", idiomatic: "A man raised to high favor—whom the emperor has greeted with respect and whom officials and commoners have learned to revere—" },
  { zh: "今而有過，帝令廢之可也，退之可也，賜之死可也，滅之可也；", literal: "now if he has faults, the Emperor ordering him dismissed is acceptable, demoting him is acceptable, granting him death is acceptable, destroying him is acceptable;", idiomatic: "may be cashiered, demoted, sentenced to death, or his house destroyed if he sins;" },
  { zh: "若夫束縛之，系媟之，輸之司寇，編之徒官，司寇小吏詈罵而榜笞之，殆非所以令眾庶見也。", literal: "but as for binding him, tying him with insult, handing him to the Minister of Justice, enrolling him among convict officials, Minister of Justice petty clerks reviling and flogging him—this is almost not the means by which to let the multitude see.", idiomatic: "but to bind him, drag him in disgrace to the Minister of Justice, register him with the convict labor corps, and let petty jailers curse and flog him—that is no sight for the people to witness." },
  { zh: "夫卑賤者習知尊貴者之一旦吾亦乃可以加此也，非所以尊尊、貴貴之化也。", literal: "Now the base and vile habitually know that for the honored and noble, one day \"I too then can apply this to them\"—this is not the means of the transformation of honoring the honored and esteeming the noble.", idiomatic: "Low folk will learn that even the mighty may one day be treated so—that trains the realm in contempt, not in reverence for rank." },
  { zh: "古者大臣有坐不廉而廢者，不謂不廉，曰簠簋不飾』；", literal: "In antiquity when great officers sat guilty of not being incorrupt and were dismissed, they were not called not incorrupt, but said \"the gui vessels are not adorned\";", idiomatic: "When a great officer was removed for corruption, the court did not call it corruption; it said his \"sacrificial vessels lacked proper polish\";" },
  { zh: "坐污穢淫亂、男女無別者，不曰污穢，曰『帷薄不修』；", literal: "when sitting guilty of filth, promiscuity, and men and women without distinction, they were not called filthy, but said \"screen curtains not repaired\";", idiomatic: "when charged with sexual scandal, they spoke of \"slack inner curtains\" instead of naming the filth;" },
  { zh: "坐罷軟不勝任者，不謂罷軟，曰『下官不職』。", literal: "when sitting guilty of weak slackness and not bearing office, they were not called weak slack, but said \"lower officials not performing duty.\"", idiomatic: "when removed for incompetence, they blamed \"subordinate officers\" rather than call him weak." },
  { zh: "故貴大臣定有其罪矣，猶未斥然正以呼之也，尚遷就而為之諱也。", literal: "Therefore though honored great officers definitely had their guilt, still they did not openly and straight call it, still bent and accommodated and for them concealed it.", idiomatic: "Even when guilt was fixed, the court still wrapped the fault in euphemism rather than shout the crime aloud." },
  { zh: "故其在大譴、大何之域者，聞譴、何則白冠氂纓，盤水加劍，造請室而請罪耳，上不執縛系引而行也；", literal: "Therefore those in the region of great reproach and great fault—when they heard reproach and fault then white cap ram's-hair tassels, basin of water with sword laid on, went to the plea chamber and pled guilt, that is all; those above did not seize, bind, tie, and lead them to go.", idiomatic: "For grave faults the minister donned white mourning garb, carried sword across a basin of water, and presented himself in the plea chamber; the emperor did not send guards to drag him in chains." },
  { zh: "其有中罪者，聞命而自弛，上不使人頸盭而加也；", literal: "Those with middle guilt, hearing the order then themselves loosened; those above did not cause men to twist the neck and apply.", idiomatic: "For middling crimes he removed his own insignia at the order; no bailiff wrenched his collar or forced the halter on him;" },
  { zh: "其有大罪者，聞命則北面再拜，跪而自裁，上不使人捽抑而刑之也。", literal: "Those with great guilt, on hearing the order then faced north and bowed twice, knelt and executed themselves; those above did not have men seize, press down, and punish them.", idiomatic: "For the gravest crimes the minister, on receiving the order, faced north, bowed twice, knelt, and took his own life; the emperor did not send men to seize him, wrestle him down, and apply the rack." },
  { zh: "曰：『子大夫自有過耳，吾遇子有禮矣。", literal: "He said: \"You, grandee, have your own faults—We treated you with ritual propriety.", idiomatic: "He would say, \"You, sir, were at fault—but I treated you with ritual propriety." },
  { zh: "』遇之有禮，故群臣自熹；", literal: "\" Treating them with propriety, therefore the host of ministers rejoiced of themselves;", idiomatic: "\" Because the ruler met them with propriety, the ministers took heart of themselves;" },
  { zh: "嬰以廉恥，故人矜節行。", literal: "They cherished integrity and shame, therefore men prized conduct and integrity.", idiomatic: "they were nurtured in integrity and shame, and men therefore prized upright conduct." },
  { zh: "上設廉恥、禮義以遇其臣不以節行報其上者，則非人類也。", literal: "When the ruler set up integrity, shame, ritual, and righteousness to meet his ministers—whoever did not repay his lord with conduct and integrity was not of the human kind.", idiomatic: "When the ruler established integrity, shame, ritual, and right to treat his ministers, anyone who failed to repay his lord with upright conduct was scarcely human." },
  { zh: "故化成俗定，則為人臣者皆顧行而忘利，守節而伏義，故可以托不御之權，可以寄六尺之孤，此厲廉恥、行禮誼之所致也，主上何喪焉！", literal: "Therefore when transformation completed and custom was fixed, those who served as ministers all looked to conduct and forgot profit, kept integrity and submitted to righteousness—therefore one could entrust authority without reins, could deposit a six-foot orphan; this is what urging integrity and shame and practicing ritual and righteousness brought about—what has the lord above lost!", idiomatic: "Once custom was formed and fixed, ministers thought of conduct and forgot profit, kept their integrity and bowed to right; then one could entrust unchecked authority and commit a fatherless child six feet tall to their care—that is what fostering integrity and shame and practicing ritual and right achieves. What has the ruler lost!" },
  { zh: "此之不為而顧彼之久行，故曰可為長太息者此也。", literal: "To neglect this and instead attend to that long practiced—therefore it is said what may be long sighed for is this.", idiomatic: "To leave this undone while clinging to what has long been practiced—this too is cause for one of the six long sighs." },
  { zh: "誼以絳侯前逮繫獄，卒無事，故以此譏上。", literal: "Yi, because the Marquis of Jiang had formerly been arrested and imprisoned yet in the end had no affair, therefore used this to reproach the emperor.", idiomatic: "Jia Yi cited how the Marquis of Jiang had once been arrested and jailed yet came to no harm, and used that episode to reproach the emperor." },
  { zh: "上深納其言，養臣下有節，是後大臣有罪，皆自殺，不受刑。", literal: "The emperor deeply took in his words, nurtured ministers below with propriety; after this when great ministers were guilty, all killed themselves and did not accept punishment.", idiomatic: "The emperor took his counsel deeply to heart and treated his ministers with ritual propriety; thereafter guilty great ministers all took their own lives rather than submit to punishment." },
  { zh: "----1冬，十月，令列侯太夫人、夫人、諸侯王子及吏二千石無得擅征捕。", literal: "----1 In winter, the tenth month, an order: the great ladies and ladies of marquises, princes of feudal lords, and officials of two thousand piculs were not to arrest or seize on their own authority.", idiomatic: "----1 In winter, the tenth month, an edict forbade the great ladies and consorts of marquises, feudal princes, and officials of two thousand piculs from arresting anyone on their own authority." },
  { zh: "----2夏，四月，赦天下。", literal: "----2 In summer, the fourth month, a general amnesty for all under Heaven.", idiomatic: "----2 In summer, the fourth month, the emperor amnestied all under Heaven." },
  { zh: "----3六月，癸酉，未央宮東闕罘罳災。", literal: "----3 In the sixth month, on guiyou, the screen curtains of the eastern tower gate of Weiyang Palace caught fire.", idiomatic: "----3 In the sixth month, on guiyou, fire destroyed the screen curtains at the eastern tower gate of Weiyang Palace." },
  { zh: "----4民有歌淮南王者曰：「一尺布，尚可縫；", literal: "----4 Among the people was one who sang of the King of Huainan, saying, \"A foot of cloth can still be sewn;", idiomatic: "----4 The people sang of the King of Huainan: \"A foot of cloth can still be sewn;" },
  { zh: "一斗粟，尚可舂；", literal: "a peck of grain can still be husked;", idiomatic: "a peck of grain can still be husked;" },
  { zh: "兄弟二人不相容！", literal: "two brothers cannot dwell together!\"", idiomatic: "two brothers cannot dwell together!\"" },
  { zh: "」帝聞而病之。", literal: "\" The emperor heard and was pained by it.", idiomatic: "\" The emperor heard it and was deeply troubled." },
  { zh: "----1夏，封淮南厲王子安等四人為列侯。", literal: "----1 In summer, he enfeoffed An and three others, sons of the Lamented King of Huainan, as marquises.", idiomatic: "----1 In summer, he enfeoffed Liu An and three other sons of the Lamented King of Huainan as marquises." },
  { zh: "賈誼知上必將復王之也，上疏諫曰：「淮南王之悖逆無道，天下孰不知其罪！", literal: "Jia Yi knew the emperor would surely restore him as king; he submitted a memorial remonstrating, saying, \"The King of Huainan's perverse rebellion against the Way—who under Heaven does not know his guilt!", idiomatic: "Jia Yi knew the emperor would surely restore him as king; he submitted a memorial remonstrating: \"The King of Huainan's perverse rebellion against the Way—who under Heaven does not know his guilt!" },
  { zh: "陛下幸而赦遷之，自疾而死，天下孰以王死之不噹！", literal: "Your Majesty graciously pardoned and banished him; he died of illness on his own—who under Heaven will say the king's death was undeserved!", idiomatic: "Your Majesty graciously pardoned and banished him; he died of his own illness—who under Heaven will say the king's death was undeserved!" },
  { zh: "今奉尊罪人之子，適足以負謗於天下耳。", literal: "Now to honor and elevate a guilty man's son is only enough to bear slander from all under Heaven.", idiomatic: "Now to honor and elevate a guilty man's son is only enough to earn slander from all under Heaven." },
  { zh: "此人少壯，豈能忘其父哉！", literal: "This man is young and in his prime—how could he forget his father!", idiomatic: "This man is young and in his prime—how could he forget his father!" },
  { zh: "白公勝所為父報仇者，大父與叔父也。", literal: "What Duke Bai Sheng did to avenge his father was against his grandfather and his father's younger brother.", idiomatic: "Duke Bai Sheng avenged his father upon his grandfather and his uncle." },
  { zh: "白公為亂，非欲取國代主，發忿快志，剡手以沖仇人之匈，固為俱靡而已。", literal: "Duke Bai raised disorder—not desiring to take the state and replace the lord, but venting wrath and satisfying will, drawing hand to pierce the enemy's breast—fundamentally it was only to perish together.", idiomatic: "Duke Bai raised rebellion not to seize the state and replace his lord, but to vent his rage and satisfy his will—to drive his hand into the enemy's breast and perish together." },
  { zh: "淮南雖小，黥布嘗用之矣，漢存，特幸耳。", literal: "Though Huainan is small, Qing Bu once used it; Han survives only by special fortune.", idiomatic: "Though Huainan is small, Qing Bu once made use of it; Han survives only by special fortune." },
  { zh: "夫擅仇人足以危漢之資，於策不便。", literal: "Now to grant a man who harbors enmity resources enough to endanger Han is in policy not advantageous.", idiomatic: "To arm a man who harbors enmity with resources enough to endanger Han is poor policy." },
  { zh: "予之眾，積之財，此非有子胥、白公報於廣都之中，即疑有專諸、荊軻起於兩柱之間，所謂假賊兵，為虎翼者也。", literal: "Give him troops, pile up wealth for him—if this is not having Zixu or Duke Bai take revenge in the broad capital, then one suspects having Zhuan Zhu or Jing Ke rise between the two pillars; it is what is called lending arms to bandits and giving wings to a tiger.", idiomatic: "Give him troops and pile up wealth for him—if this is not to breed another Zixu or Duke Bai taking revenge in the capital, it is to risk another Zhuan Zhu or Jing Ke rising between the palace pillars; it is what men call lending arms to bandits and giving wings to a tiger." },
  { zh: "願陛下少留計！", literal: "Your Majesty, we beg you to pause and consider!", idiomatic: "Your Majesty, I beg you to pause and reconsider!" },
  { zh: "」上弗聽。", literal: "\" The emperor did not listen.", idiomatic: "\" The emperor did not listen." },
  { zh: "----2有長星出於東方。", literal: "----2 A long comet appeared in the east.", idiomatic: "----2 A long comet appeared in the east." },
  { zh: "----1春，大旱。", literal: "----1 In spring, great drought.", idiomatic: "----1 In spring, a great drought." },
  { zh: "----1冬，上行幸甘泉。", literal: "----1 In winter, the emperor traveled in person to Sweet Springs.", idiomatic: "----1 In winter, the emperor traveled in person to Sweet Springs." },
  { zh: "----2將軍薄昭殺漢使者。", literal: "----2 General Bo Zhao killed a Han envoy.", idiomatic: "----2 General Bo Zhao killed a Han envoy." },
  { zh: "帝不忍加誅，使公卿從之飲酒。", literal: "The emperor could not bear to execute him and had the high ministers drink with him.", idiomatic: "The emperor could not bear to execute him outright and had the high ministers drink with him." },
  { zh: "欲令自引分，昭不肯；", literal: "He wished to cause him to take his own portion of blame; Zhao refused;", idiomatic: "He hoped Zhao would take his own life; Zhao refused;" },
  { zh: "使群臣喪服往哭之，乃自殺。", literal: "he had the host of ministers go in mourning garb to wail for him—then Zhao killed himself.", idiomatic: "he sent the ministers in mourning garb to wail for him—then Zhao killed himself." },
  { zh: "::臣光曰：李德裕以為：「漢文帝誅薄昭，斷則明矣，於義則未安也。", literal: ":: Your servant Guang says: Li Deyu held that \"Emperor Wen of Han executed Bo Zhao—decisive, it was clear; in righteousness, it was not settled.", idiomatic: ":: Your servant Guang says: Li Deyu held that \"Emperor Wen of Han executed Bo Zhao—decisive, it was clear; in righteousness, it was not settled." },
  { zh: "秦康送晉文，興如存之感；", literal: "Duke Kang of Qin escorted Duke Wen of Jin—the stirring was as if he still lived;", idiomatic: "Duke Kang of Qin escorted Duke Wen of Jin—the stirring was as if he still lived;" },
  { zh: "況太后尚存，唯一弟薄昭，斷之不疑，非所以慰母氏之心也。", literal: "how much more when the empress dowager still lived and Bo Zhao was her only brother—to cut him off without doubt was not the means to comfort the mother's heart.", idiomatic: "how much more when the empress dowager still lived and Bo Zhao was her only brother—to cut him off without hesitation was no comfort to a mother's heart." },
  { zh: "」臣愚以為法者天下之公器，惟善持法者，親疏如一，無所不行，則人莫敢有所恃而犯之也。", literal: "\" Your servant is foolish and holds that law is the public vessel of all under Heaven; only one skilled at holding law treats kin and stranger as one, applies it everywhere without exception—then no man dares rely on anything and transgress it.", idiomatic: "\" Your servant holds that law is the public instrument of all under Heaven; only one skilled at upholding law treats kin and stranger alike and applies it without exception—then no one dares rely on favor and transgress it." },
  { zh: "夫薄昭雖素稱長者，文帝不為置賢師傅而用之典兵；", literal: "Now though Bo Zhao was always called a worthy elder, Emperor Wen did not set up worthy teachers and tutors for him but used him to command troops;", idiomatic: "Though Bo Zhao was always called a worthy elder, Emperor Wen did not assign him worthy teachers and tutors but used him to command troops;" },
  { zh: "驕而犯上，至於殺漢使者，非有恃而然乎！", literal: "proud and transgressing against his superiors, reaching the point of killing a Han envoy—is this not having something to rely on and therefore becoming so!", idiomatic: "grew proud, transgressed against his superiors, and killed a Han envoy—did he not act so because he had something to rely on!" },
  { zh: "若又從而赦之，則與成、哀之世何異哉！", literal: "If one again followed by pardoning him, how would it differ from the age of Cheng and Ai!", idiomatic: "If the emperor then pardoned him, how would that differ from the age of Cheng and Ai!" },
  { zh: "魏文帝嘗稱漢文帝之美，而不取其殺薄昭，曰：「-{舅后}-之家，但當養育以恩而不當假藉以權，既觸罪法，又不得不害。", literal: "Emperor Wen of Wei once praised Emperor Wen of Han's excellence yet did not approve his killing Bo Zhao, saying, \"The house of -{舅后}- should only be nurtured with kindness and must not be lent authority; once they touch the penal law, one again cannot but harm them.", idiomatic: "Emperor Wen of Wei once praised Emperor Wen of Han's excellence yet did not approve his killing Bo Zhao, saying, \"The house of -{舅后}- should only be nurtured with kindness and must not be lent authority; once they touch the penal law, one cannot but punish them." },
  { zh: "」譏文帝之始不防閒昭也，斯言得之矣。", literal: "\" He reproached Emperor Wen for not guarding against Bo Zhao at the start—this saying hits the mark.", idiomatic: "\" He reproached Emperor Wen for not guarding against Bo Zhao at the start—this saying hits the mark." },
  { zh: "然則欲慰母心者，將慎之於始乎！", literal: "If so, one who wishes to comfort a mother's heart will be careful at the beginning!", idiomatic: "If so, one who wishes to comfort a mother's heart must be careful at the beginning!" },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
